import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallGuest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallGuest";

export async function test_api_guest_registration(connection: api.IConnection) {
  // Generate minimal guest creation data with realistic IP address and current timestamp
  const guestCreate = {
    ip: [
      192,
      168,
      typia.random<
        number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>
      >(),
      typia.random<
        number & tags.Type<"uint32"> & tags.Minimum<0> & tags.Maximum<255>
      >(),
    ].join("."),
    created_at: new Date().toISOString(),
  } satisfies IShoppingMallGuest.ICreate;

  // Call the guest join API to register new guest user
  const authorized: IShoppingMallGuest.IAuthorized =
    await api.functional.auth.guest.join(connection, { body: guestCreate });
  typia.assert(authorized);

  // Validate the guest id is a valid UUID
  typia.assert<string & tags.Format<"uuid">>(authorized.id);

  // Validate token structure and contents
  typia.assert(authorized.token);
  typia.assert<string & tags.Format<"date-time">>(authorized.token.expired_at);
  typia.assert<string & tags.Format<"date-time">>(
    authorized.token.refreshable_until,
  );

  // Verify the expires_at is a valid date-time string
  typia.assert<string & tags.Format<"date-time">>(authorized.expires_at);

  // Additional predicates for clarity
  TestValidator.predicate(
    "token access is non-empty string",
    typeof authorized.token.access === "string" &&
      authorized.token.access.length > 0,
  );
  TestValidator.predicate(
    "token refresh is non-empty string",
    typeof authorized.token.refresh === "string" &&
      authorized.token.refresh.length > 0,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallPlatformConfig } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPlatformConfig";

/**
 * This e2e test validates the deletion of a platform configuration by an admin
 * user.
 *
 * The process is as follows:
 *
 * 1. Authenticate as an admin user by calling the join API.
 * 2. Create a platform configuration using the create API.
 * 3. Delete the created platform configuration by its id via the delete API.
 * 4. Attempt to retrieve the deleted platform configuration which is expected to
 *    fail.
 *
 * This test ensures that the platform configuration lifecycle (creation,
 * deletion, and validation of deletion) works correctly for an admin user.
 */
export async function test_api_platformconfig_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin authentication
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "complex_password_1234";
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        full_name: RandomGenerator.name(),
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create platform configuration to be deleted
  const createBody = {
    config_name: `test_config_${RandomGenerator.alphaNumeric(8)}`,
    config_value: RandomGenerator.alphabets(10),
    description: `Temporary test config created on ${new Date().toISOString()}`,
  } satisfies IShoppingMallPlatformConfig.ICreate;
  const createdConfig: IShoppingMallPlatformConfig =
    await api.functional.shoppingMall.admin.platformConfigs.create(connection, {
      body: createBody,
    });
  typia.assert(createdConfig);

  // 3. Delete the created platform configuration
  await api.functional.shoppingMall.admin.platformConfigs.erase(connection, {
    id: createdConfig.id,
  });

  // 4. Validate deletion by attempting to delete again expecting failure
  await TestValidator.error(
    "deleting non-existent platform config should fail",
    async () => {
      await api.functional.shoppingMall.admin.platformConfigs.erase(
        connection,
        {
          id: createdConfig.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallRefundRequest";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallUserRole";

/**
 * Validate admin retrieval of refund requests with filtering and pagination.
 *
 * Steps:
 *
 * 1. Admin registration via /auth/admin/join with realistic email and profile.
 * 2. Admin login via /auth/admin/login to obtain authorization tokens.
 * 3. Ensure user roles exist for admin and sample customer(s) via
 *    /shoppingMall/admin/userRoles.
 * 4. Perform refund requests search via /shoppingMall/admin/refundRequests/index
 *    with filters and pagination.
 * 5. Validate returned refund request summaries including correctness of fields:
 *    id, shopping_mall_order_id, shopping_mall_customer_id, refund_amount,
 *    refund_reason, refund_status, created_at, updated_at.
 * 6. Validate pagination metadata including current page, limit, total records,
 *    pages.
 *
 * The test ensures the admin can view refund requests accurately, with valid
 * filtering and sorted pagination.
 */
export async function test_api_refund_request_index(
  connection: api.IConnection,
) {
  // 1. Admin registration
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: "StrongPassw0rd!",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  // 2. Admin login
  const adminLoginBody = {
    email: adminEmail,
    password: "StrongPassw0rd!",
    href: "https://admin.shoppingmall.example.com/dashboard",
    referrer: "https://admin.shoppingmall.example.com/login",
  } satisfies IShoppingMallAdmin.ILogin;
  const loggedInAdmin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(loggedInAdmin);

  // 3. Ensure user roles exist for admin and a sample customer
  // Use the admin user ID
  const adminUserRoleBody = {
    user_id: admin.id,
    role_name: "admin",
  } satisfies IShoppingMallUserRole.ICreate;
  const adminUserRole: IShoppingMallUserRole =
    await api.functional.shoppingMall.admin.userRoles.create(connection, {
      body: adminUserRoleBody,
    });
  typia.assert(adminUserRole);

  // Create a sample customer to assign role
  // For testing, we generate a random UUID (simulate existing customer)
  const customerId = typia.random<string & tags.Format<"uuid">>();
  const customerUserRoleBody = {
    user_id: customerId,
    role_name: "customer",
  } satisfies IShoppingMallUserRole.ICreate;
  const customerUserRole: IShoppingMallUserRole =
    await api.functional.shoppingMall.admin.userRoles.create(connection, {
      body: customerUserRoleBody,
    });
  typia.assert(customerUserRole);

  // 4. Perform refund requests search with filters and pagination
  const refundRequestSearchBody = {
    page: 1,
    limit: 10,
    refund_status: "pending",
    customer_id: customerId,
    order_code: "ORD", // partial code to search
    sort_by: "created_at",
    order_direction: "desc",
  } satisfies IShoppingMallRefundRequest.IRequest;

  const refundRequestPage: IPageIShoppingMallRefundRequest.ISummary =
    await api.functional.shoppingMall.admin.refundRequests.index(connection, {
      body: refundRequestSearchBody,
    });
  typia.assert(refundRequestPage);

  // 5. Validate refund request summaries
  // Validate pagination
  TestValidator.predicate(
    "pagination current page is 1",
    refundRequestPage.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination limit is 10",
    refundRequestPage.pagination.limit === 10,
  );
  TestValidator.predicate(
    "pagination records non-negative",
    refundRequestPage.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pagination pages non-negative",
    refundRequestPage.pagination.pages >= 0,
  );

  // Validate each refund request summary
  for (const request of refundRequestPage.data) {
    typia.assert<IShoppingMallRefundRequest.ISummary>(request);
    // Check IDs format
    TestValidator.predicate(
      "refund request id is uuid",
