import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSkuInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSkuInventory";

/**
 * Test the process of creating a SKU inventory record by an admin user.
 *
 * This test covers the full scenario:
 *
 * 1. Admin user registration (join)
 * 2. Product creation as a prerequisite for SKU inventory
 * 3. Inspecting created product to retrieve SKU for inventory linkage
 * 4. Creating SKU inventory record with proper quantity and stock status
 * 5. Validating the returned SKU inventory data for correctness
 */
export async function test_api_sku_inventory_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin user join
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "StrongPassword123!",
        full_name: RandomGenerator.name(),
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create product as prerequisite
  const productCreateBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(3),
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 4,
      wordMax: 8,
    }),
    brand: RandomGenerator.name(2),
  } satisfies IShoppingMallProduct.ICreate;

  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.admin.products.create(connection, {
      body: productCreateBody,
    });
  typia.assert(product);

  // 3. Retrieve a SKU from the created product
  TestValidator.predicate(
    "product has at least one SKU",
    product.shopping_mall_product_skus !== undefined &&
      product.shopping_mall_product_skus.length > 0,
  );
  const sku: IShoppingMallProductSku = product.shopping_mall_product_skus![0];
  typia.assert(sku);

  // 4. Create SKU inventory
  const skuInventoryCreateBody = {
    shopping_mall_product_sku_id: sku.id,
    quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<0>>(),
    stock_status: "in stock",
  } satisfies IShoppingMallSkuInventory.ICreate;

  const skuInventory: IShoppingMallSkuInventory =
    await api.functional.shoppingMall.admin.skuInventories.create(connection, {
      body: skuInventoryCreateBody,
    });
  typia.assert(skuInventory);

  // 5. Validate the created inventory record
  TestValidator.equals(
    "SKU inventory links to correct SKU",
    skuInventory.shopping_mall_product_sku_id,
    sku.id,
  );
  TestValidator.predicate(
    "SKU inventory quantity is non-negative",
    skuInventory.quantity >= 0,
  );
  TestValidator.equals(
    "SKU inventory stock status",
    skuInventory.stock_status,
    "in stock",
  );
  typia.assert(skuInventory.id);
  TestValidator.predicate(
    "SKU inventory has a created_at timestamp",
    skuInventory.created_at !== null && skuInventory.created_at !== undefined,
  );
  TestValidator.predicate(
    "SKU inventory has an updated_at timestamp",
    skuInventory.updated_at !== null && skuInventory.updated_at !== undefined,
  );
}

