    productCreateBody.name,
  );
  TestValidator.equals(
    "product description matches input",
    product.description ?? null,
    productCreateBody.description ?? null,
  );
  TestValidator.equals(
    "product brand matches input",
    product.brand ?? null,
    productCreateBody.brand ?? null,
  );

  // Validate timestamp format and ordering
  TestValidator.predicate(
    "product created_at is valid ISO date",
    typeof product.created_at === "string" &&
      !Number.isNaN(Date.parse(product.created_at)),
  );
  TestValidator.predicate(
    "product updated_at is valid ISO date",
    typeof product.updated_at === "string" &&
      !Number.isNaN(Date.parse(product.updated_at)),
  );

  TestValidator.predicate(
    "product updated_at >= created_at",
    new Date(product.updated_at).getTime() >=
      new Date(product.created_at).getTime(),
  );

  // deleted_at must be null or undefined on creation
  TestValidator.predicate(
    "product deleted_at is null or undefined",
    product.deleted_at === null || product.deleted_at === undefined,
  );
}

