export async function test_api_sellers_list_retrieval_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller joins the platform
  const sellerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: RandomGenerator.alphaNumeric(12),
    store_name: RandomGenerator.name(2),
  } satisfies IShoppingMallSeller.ICreate;

  const sellerAuthorized: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: sellerJoinBody,
    });
  typia.assert(sellerAuthorized);

  // 2. Seller logs in
  const sellerLoginBody = {
    email: sellerJoinBody.email,
    password: sellerJoinBody.password,
    href: "https://test.client.app/",
    referrer: "https://test.referrer.app/",
  } satisfies IShoppingMallSeller.ILogin;

  const loginAuthorized: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.login(connection, {
      body: sellerLoginBody,
    });
  typia.assert(loginAuthorized);

  // 3. Retrieve sellers list filtered and paginated
  // Use pagination parameters within allowed range
  const requestBody = {
    email: undefined,
    store_name: undefined,
    created_at_from: undefined,
    created_at_to: undefined,
    page: 1,
    limit: 20,
    sort_by: "created_at" as const,
    sort_order: "desc" as const,
  } satisfies IShoppingMallSeller.IRequest;

  const sellersPage: IPageIShoppingMallSeller.ISummary =
    await api.functional.shoppingMall.seller.sellers.indexSellers(connection, {
      body: requestBody,
    });
  typia.assert(sellersPage);

  // Validate pagination properties
  TestValidator.predicate(
    "pagination has positive current page",
    sellersPage.pagination.current > 0,
  );
  TestValidator.predicate(
    "pagination limit is within allowed bounds",
    sellersPage.pagination.limit > 0 && sellersPage.pagination.limit <= 100,
  );
  TestValidator.predicate(
    "pagination pages is positive or zero",
    sellersPage.pagination.pages >= 0,
  );
  TestValidator.predicate(
    "pagination records count is non-negative",
    sellersPage.pagination.records >= 0,
  );

  // Validate data array
  TestValidator.predicate("data is an array", Array.isArray(sellersPage.data));

  for (const seller of sellersPage.data) {
    typia.assert(seller); // Validate seller summary structure
    TestValidator.predicate(
      "seller id is non-empty string",
      typeof seller.id === "string" && seller.id.length > 0,
    );
    TestValidator.predicate(
      "seller email format",
      /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(seller.email),
    );
    TestValidator.predicate(
      "seller store_name is not empty string",
      typeof seller.store_name === "string" && seller.store_name.length > 0,
    );
    // created_at and updated_at should be ISO date-time strings
    TestValidator.predicate(
      "created_at valid ISO string",
      !Number.isNaN(Date.parse(seller.created_at)),
    );
    TestValidator.predicate(
      "updated_at valid ISO string",
      !Number.isNaN(Date.parse(seller.updated_at)),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProductCategory";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

/**
 * Test retrieving a filtered and paginated list of shopping mall product
 * categories.
 *
 * This test verifies the category search API which supports complex filtering
 * and pagination. The test covers scenarios including:
 *
 * - No filters, retrieving all categories paginated
 * - Filtering by partial category name matches
 * - Filtering by parent category ID (including null for root categories)
 * - Pagination with different page numbers and limits, including boundary values
 * - Sorting by name, created_at, updated_at with ascending and descending orders
 *
 * Validation points:
 *
 * - Response data has correct type and contains only expected properties
 * - Pagination metadata correctness (current page, record count, total pages)
 * - Filtering results must respect filters, e.g., all returned categories have
 *   names matching filter when applied
 * - Filtering by parent_id limits to categories with that parent_id
 * - Sorting order is properly applied
 * - No sensitive or unauthorized data leaking in category summaries
 *
 * This test uses only the public category listing API (PATCH
 * /shoppingMall/productCategories) without authentication.
 *
 * Multiple queries are performed to cover combinations of filters and
 * pagination to validate consistent API behavior.
 */
export async function test_api_product_category_search_and_pagination(
  connection: api.IConnection,
) {
  // Helper function to validate pagination metadata
  function validatePagination(
    pagination: IPage.IPagination,
    expectedPage: number,
    expectedLimit: number,
    expectedRecords: number,
  ) {
    TestValidator.equals(
      "pagination current page",
      pagination.current,
      expectedPage,
    );
    TestValidator.equals("pagination limit", pagination.limit, expectedLimit);
    TestValidator.predicate(
      "pagination records non-negative",
      pagination.records >= 0,
    );
    TestValidator.predicate("pagination pages positive", pagination.pages > 0);
    TestValidator.predicate(
      "pagination pages correct",
      pagination.pages >= Math.ceil(pagination.records / pagination.limit),
    );
  }

  // Test case 1: No filters, default pagination
  {
    const requestBody = {} satisfies IShoppingMallProductCategory.IRequest;
    const response = await api.functional.shoppingMall.productCategories.index(
      connection,
      { body: requestBody },
    );
    typia.assert(response);

    validatePagination(response.pagination, 1, 20, response.pagination.records);
    TestValidator.predicate(
      "empty filter returns some data",
      response.data.length > 0,
    );

    // All items have required properties
    for (const category of response.data) {
      typia.assert(category);
      TestValidator.predicate(
        "category id is uuid",
        /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
          category.id,
        ),
      );
      TestValidator.predicate(
        "category name is non-empty",
        category.name.length > 0,
      );
      // parent_id can be null or uuid string
      if (category.parent_id !== null && category.parent_id !== undefined) {
        TestValidator.predicate(
          "category parent_id is uuid",
          /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(
            category.parent_id,
          ),
        );
      }
    }
  }

  // Test case 2: Filter by partial name match
  {
    const partial = RandomGenerator.substring(
      "Electronics Appliances Clothes Sports Garden",
    );
    const requestBody = {
      filter_name: partial,
      page: 1,
      limit: 10,
      sort_by: "name",
      order: "asc",
    } satisfies IShoppingMallProductCategory.IRequest;

    const response = await api.functional.shoppingMall.productCategories.index(
      connection,
      { body: requestBody },
    );
    typia.assert(response);

    validatePagination(response.pagination, 1, 10, response.pagination.records);
    for (const category of response.data) {
      typia.assert(category);
      TestValidator.predicate(
        `category name contains filter_name: ${partial}`,
        category.name.toLowerCase().includes(partial.toLowerCase()),
      );
    }
  }

  // Test case 3: Filter by parent_id with realistic UUID
  {
    // Pick a random parent_id from first page categories or null
    const initialResponse =
      await api.functional.shoppingMall.productCategories.index(connection, {
        body: { limit: 50 } satisfies IShoppingMallProductCategory.IRequest,
      });
    typia.assert(initialResponse);
    const parentCandidateIds = initialResponse.data
      .map((c) => c.id)
      .filter((id) => id !== undefined && id !== null);
    const parentId =
      parentCandidateIds.length > 0
        ? RandomGenerator.pick(parentCandidateIds)
        : null;

    const requestBody = {
      filter_parent_id: parentId,
      page: 1,
      limit: 15,
      sort_by: "created_at",
      order: "desc",
    } satisfies IShoppingMallProductCategory.IRequest;

    const response = await api.functional.shoppingMall.productCategories.index(
      connection,
      { body: requestBody },
    );
    typia.assert(response);

    validatePagination(response.pagination, 1, 15, response.pagination.records);

    // All returned categories must have the specified parent_id
    for (const category of response.data) {
      typia.assert(category);
      TestValidator.equals(
        "category parent_id matches filter",
        category.parent_id ?? null,
        parentId,
      );
    }
  }

  // Test case 4: Pagination with page and limit boundaries
  {
    const requestBody = {
      page: 2,
      limit: 5,
      sort_by: "updated_at",
      order: "asc",
    } satisfies IShoppingMallProductCategory.IRequest;

    const response = await api.functional.shoppingMall.productCategories.index(
      connection,
      { body: requestBody },
    );
    typia.assert(response);

    validatePagination(response.pagination, 2, 5, response.pagination.records);
    TestValidator.predicate(
      "page 2 returns up to 5 items",
      response.data.length <= 5,
    );
  }

  // Test case 5: Sorting checks
  for (const sortBy of ["name", "created_at", "updated_at"] as const) {
    for (const order of ["asc", "desc"] as const) {
      const requestBody = {
        sort_by: sortBy,
        order: order,
        limit: 10,
      } satisfies IShoppingMallProductCategory.IRequest;
      const response =
        await api.functional.shoppingMall.productCategories.index(connection, {
          body: requestBody,
        });
      typia.assert(response);
      validatePagination(
        response.pagination,
        response.pagination.current,
        10,
        response.pagination.records,
      );

      // Check sorting order by verifying sequence
      const sortableVals: (string | undefined)[] = response.data
        .map((cat) => {
          switch (sortBy) {
            case "name":
              return cat.name.toLowerCase();
            case "created_at":
            case "updated_at":
              // These timestamps may not exist in summary, skip ordering validation for those
              // Because IShoppingMallProductCategory.ISummary does NOT have these properties, so skip check here
              return undefined;
            default:
              return undefined;
          }
        })
        .filter((v) => v !== undefined) as string[];

      if (sortableVals.length >= 2) {
        for (let i = 1; i < sortableVals.length; i++) {
          if (order === "asc") {
            TestValidator.predicate(
              `sorted ascending by ${sortBy}`,
              sortableVals[i - 1]! <= sortableVals[i]!,
            );
          } else {
            TestValidator.predicate(
              `sorted descending by ${sortBy}`,
              sortableVals[i - 1]! >= sortableVals[i]!,
            );
          }
        }
      }
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

export async function test_api_product_category_detail_by_admin(
  connection: api.IConnection,
) {
  // Authenticate as admin before access
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "securePassword123",
        full_name: RandomGenerator.name(),
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // Access a valid product category detail (presumed existing UUID)
  const categoryId: string & tags.Format<"uuid"> = typia.random<
    string & tags.Format<"uuid">
  >();
  const category: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.at(connection, {
      id: categoryId,
    });
  typia.assert(category);

  // Validate required fields for the retrieved category
  TestValidator.predicate(
    "category id is UUID format",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      category.id,
    ),
  );
  TestValidator.predicate(
    "category name is string",
    typeof category.name === "string",
  );
  TestValidator.predicate(
    "category created_at ISO date",
    typeof category.created_at === "string",
  );
  TestValidator.predicate(
    "category updated_at ISO date",
    typeof category.updated_at === "string",
  );

  // Validate deleted_at property explicit null or string (ISO datetime)
  if (category.deleted_at === null) {
    TestValidator.equals("deleted_at is null", category.deleted_at, null);
  } else if (category.deleted_at !== undefined) {
    TestValidator.predicate(
      "deleted_at is ISO datetime",
      typeof category.deleted_at === "string",
    );
  }

  // Validate optional nullable parent_id field
  if (category.parent_id === null) {
    TestValidator.equals("parent_id null explicit", category.parent_id, null);
  } else if (category.parent_id !== undefined) {
    TestValidator.predicate(
      "parent_id is UUID string",
      typeof category.parent_id === "string",
    );
  }

  // Test error handling with invalid category id
  await TestValidator.error(
    "invalid category id should cause error",
    async () => {
      await api.functional.shoppingMall.admin.productCategories.at(connection, {
        id: typia.random<string & tags.Format<"uuid">>(), // presumably non-existent
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallStockAdjustment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallStockAdjustment";

/**
 * E2E test to validate detailed stock adjustment retrieval by ID as a seller.
 *
 * The full test covers:
 *
 * 1. Seller registration and authentication.
 * 2. Product creation with unique code and descriptive information.
 * 3. Product SKU creation with unique SKU code, price, and variant attributes.
 * 4. Stock adjustment creation for the SKU, with 'addition' adjustment type,
 *    quantity > 0, and actor as the seller.
 * 5. Retrieving the stock adjustment by its unique ID.
 * 6. Ensuring retrieved data matches exactly the created stock adjustment
 *    including SKU ID, adjustment type, quantity, actor type, actor ID, and
 *    created_at timestamp.
 */
export async function test_api_stock_adjustment_detail_by_seller(
  connection: api.IConnection,
) {
  // 1. Register and authenticate a new seller account
  const sellerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "StrongP@ssw0rd",
    store_name: RandomGenerator.name(2),
  } satisfies IShoppingMallSeller.ICreate;
  const seller = await api.functional.auth.seller.join(connection, {
    body: sellerBody,
  });
  typia.assert(seller);

  // 2. Create a product
  const productBody = {
    code: `PROD-${RandomGenerator.alphaNumeric(8)}`,
    name: RandomGenerator.name(3),
    description: RandomGenerator.content({ paragraphs: 1 }),
    brand: RandomGenerator.name(1),
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    { body: productBody },
  );
  typia.assert(product);

  // 3. Create a product SKU
  const skuBody = {
    sku_code: `SKU-${RandomGenerator.alphaNumeric(6)}`,
    price: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    attributes_json: JSON.stringify({
      color: RandomGenerator.pick(["red", "green", "blue"] as const),
      size: RandomGenerator.pick(["S", "M", "L"] as const),
    }),
  } satisfies IShoppingMallProductSku.ICreate;
  const sku = await api.functional.shoppingMall.seller.products.skus.createSku(
    connection,
    { productCode: product.code, body: skuBody },
  );
  typia.assert(sku);

  // 4. Create stock adjustment
  const adjustmentBody = {
    shopping_mall_product_sku_id: sku.id,
    adjustment_type: "addition",
    quantity: typia.random<number & tags.Type<"int32"> & tags.Minimum<1>>(),
    actor_type: "seller",
    actor_id: seller.id,
  } satisfies IShoppingMallStockAdjustment.ICreate;
  const adjustment =
    await api.functional.shoppingMall.seller.stockAdjustments.create(
      connection,
      { body: adjustmentBody },
