import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

export async function test_api_shopping_cart_items_patch_by_customer(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "TestPassword123!",
    nickname: RandomGenerator.name(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customerAuthorized = await api.functional.auth.customer.join(
    connection,
    {
      body: customerCreate,
    },
  );
  typia.assert(customerAuthorized);

  // 2. Login as the new customer
  const customerLogin = {
    email: customerCreate.email,
    password: "TestPassword123!",
    href: "https://example.com/",
    referrer: "https://example.com/",
  } satisfies IShoppingMallCustomer.ILogin;
  const customerLoggedIn = await api.functional.auth.customer.login(
    connection,
    {
      body: customerLogin,
    },
  );
  typia.assert(customerLoggedIn);

  // 3. Register a seller
  const sellerCreate = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SellerPassword123!",
    store_name: RandomGenerator.name(),
  } satisfies IShoppingMallSeller.ICreate;
  const sellerAuthorized = await api.functional.auth.seller.join(connection, {
    body: sellerCreate,
  });
  typia.assert(sellerAuthorized);

  // 4. Login the seller
  const sellerLogin = {
    email: sellerCreate.email,
    password: "SellerPassword123!",
    href: "https://seller.example.com/",
    referrer: "https://seller.example.com/",
  } satisfies IShoppingMallSeller.ILogin;
  const sellerLoggedIn = await api.functional.auth.seller.login(connection, {
    body: sellerLogin,
  });
  typia.assert(sellerLoggedIn);

  // 5. Seller creates a product
  const productCreate = {
    code: `PROD-${RandomGenerator.alphaNumeric(6).toUpperCase()}`,
    name: RandomGenerator.name(3),
    description: RandomGenerator.paragraph({ sentences: 3 }),
  } satisfies IShoppingMallProduct.ICreate;
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: productCreate,
    },
  );
  typia.assert(product);

  // 6. Seller creates SKUs for the product
  const skuIds: string[] = [];
  const numberOfSkus = 3;
  for (let i = 0; i < numberOfSkus; i++) {
    const skuCreate = {
      sku_code: `${productCreate.code}-SKU${i + 1}`,
      price: typia.random<
        number & tags.Type<"int32"> & tags.Minimum<100> & tags.Maximum<10000>
      >(),
      attributes_json: JSON.stringify({
        color: ["red", "green", "blue"][i],
        size: ["S", "M", "L"][i],
      }),
    } satisfies IShoppingMallProductSku.ICreate;
    const sku =
      await api.functional.shoppingMall.seller.products.skus.createSku(
        connection,
        {
          productCode: productCreate.code,
          body: skuCreate,
        },
      );
    typia.assert(sku);
    skuIds.push(sku.id);
  }

  // 7. Create a new shopping cart for the customer session
  // NOTE: customerAuthorized does not provide session ID, so reuse customer id as session id for test
  const shoppingCartCreate = {
    shopping_mall_customer_id: customerAuthorized.id,
    shopping_mall_customer_session_id: customerAuthorized.id,
  } satisfies IShoppingMallShoppingCart.ICreate;
  const shoppingCart =
    await api.functional.shoppingMall.customer.shoppingCarts.create(
      connection,
      {
        body: shoppingCartCreate,
      },
    );
  typia.assert(shoppingCart);

  // 8. Add SKUs with quantities to shopping cart
  const itemsAdd: IShoppingMallCartItem.ICreate[] = skuIds.map((id, index) => ({
    shopping_mall_product_sku_id: id,
    quantity: index + 1,
  }));

  let patchedCartItems =
    await api.functional.shoppingMall.customer.shoppingCarts.items.index(
      connection,
      {
        cartId: shoppingCart.id,
        body: {
          items: itemsAdd,
        } satisfies IShoppingMallShoppingCartItem.IRequest,
      },
    );
  typia.assert(patchedCartItems);

  // 9. Update quantities in the cart, doubling each
  const itemsUpdate: IShoppingMallCartItem.ICreate[] =
    patchedCartItems.data.map((item) => ({
      shopping_mall_product_sku_id: item.shopping_mall_product_sku_id,
      quantity: item.quantity * 2,
    }));

  patchedCartItems =
    await api.functional.shoppingMall.customer.shoppingCarts.items.index(
      connection,
      {
        cartId: shoppingCart.id,
        body: {
          items: itemsUpdate,
        } satisfies IShoppingMallShoppingCartItem.IRequest,
      },
    );
  typia.assert(patchedCartItems);

  // 10. Remove last SKU by excluding it
  const itemsRemoveLast: IShoppingMallCartItem.ICreate[] = itemsUpdate.slice(
    0,
    -1,
  );

  patchedCartItems =
    await api.functional.shoppingMall.customer.shoppingCarts.items.index(
      connection,
      {
        cartId: shoppingCart.id,
        body: {
          items: itemsRemoveLast,
        } satisfies IShoppingMallShoppingCartItem.IRequest,
      },
    );
  typia.assert(patchedCartItems);

  // 11. Final validation
  TestValidator.equals(
    "final cart items count",
    patchedCartItems.data.length,
    itemsRemoveLast.length,
  );
  for (let i = 0; i < itemsRemoveLast.length; i++) {
    TestValidator.equals(
      `cart item quantity SKU ${i + 1}`,
      patchedCartItems.data[i].quantity,
      itemsRemoveLast[i].quantity,
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";

/**
 * Test successful JWT token refresh for a logged-in customer.
 *
 * This test covers the full lifecycle of token refreshing for a newly
 * registered customer user. It verifies that after customer registration, the
 * refresh token can be used to obtain new JWT tokens successfully. It also
 * validates error responses to invalid refresh token values.
 *
 * Steps:
 *
 * 1. Register a new customer user via /auth/customer/join.
 * 2. Extract the refresh token from the authorized customer response.
 * 3. Use the refresh token to call /auth/customer/refresh and obtain new tokens.
 * 4. Verify the refreshed token response.
 * 5. Attempt refresh with invalid tokens and verify failure responses.
 */
export async function test_api_customer_token_refresh_with_valid_refresh_token(
  connection: api.IConnection,
) {
  // Step 1: Register a new customer
  const newCustomerBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "validPassword123!",
    nickname: RandomGenerator.name(),
  } satisfies IShoppingMallCustomer.ICreate;

  const authorizedCustomer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: newCustomerBody,
    });
  typia.assert(authorizedCustomer);

  // Step 2: Extract the refresh token
  const initialRefreshToken: string = authorizedCustomer.token.refresh;

  // Step 3: Refresh JWT tokens using the refresh token
  const refreshBody = {
    refresh_token: initialRefreshToken,
  } satisfies IShoppingMallCustomer.IRefresh;

  const refreshedCustomer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.refresh(connection, {
      body: refreshBody,
    });
  typia.assert(refreshedCustomer);

  // Step 4: Validate refreshed tokens are different from initial tokens
  TestValidator.predicate(
    "refresh token should be updated",
    authorizedCustomer.token.refresh !== refreshedCustomer.token.refresh,
  );
  TestValidator.predicate(
    "access token should be updated",
    authorizedCustomer.token.access !== refreshedCustomer.token.access,
  );

  // Step 5: Test invalid refresh tokens
  await TestValidator.error("refresh token null should fail", async () => {
    await api.functional.auth.customer.refresh(connection, {
      body: { refresh_token: "" } satisfies IShoppingMallCustomer.IRefresh,
    });
  });

  await TestValidator.error("refresh token invalid should fail", async () => {
    await api.functional.auth.customer.refresh(connection, {
      body: {
        refresh_token: "invalid-token",
      } satisfies IShoppingMallCustomer.IRefresh,
    });
  });
}

