  const productCode: string = RandomGenerator.alphaNumeric(10).toUpperCase();
  const productName: string = RandomGenerator.name();
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        code: productCode,
        name: productName,
        description: RandomGenerator.paragraph({ sentences: 5 }),
        brand: RandomGenerator.name(),
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // 4. Seller creates SKU for the product
  const skuCode: string = RandomGenerator.alphaNumeric(8).toUpperCase();
  const skuPrice: number = Math.floor(Math.random() * 1000) + 100; // Price between 100 and 1099
  const skuAttributesJson = JSON.stringify({
    color: RandomGenerator.pick(["red", "blue", "green"]),
    size: RandomGenerator.pick(["S", "M", "L"]),
  });
  const sku: IShoppingMallProductSku =
    await api.functional.shoppingMall.seller.products.skus.createSku(
      connection,
      {
        productCode: productCode,
        body: {
          sku_code: skuCode,
          price: skuPrice,
          attributes_json: skuAttributesJson,
        } satisfies IShoppingMallProductSku.ICreate,
      },
    );
  typia.assert(sku);

  // 5. Customer creates a shopping cart
  const cart: IShoppingMallShoppingCart =
    await api.functional.shoppingMall.customer.shoppingCarts.create(
      connection,
      {
        body: {
          shopping_mall_customer_id: customer1.id,
          shopping_mall_customer_session_id: typia.random<
            string & tags.Format<"uuid">
          >(),
        } satisfies IShoppingMallShoppingCart.ICreate,
      },
    );
  typia.assert(cart);

  // 6. Add SKU item to customer's shopping cart
  const cartItem: IShoppingMallCartItem =
    await api.functional.shoppingMall.customer.shoppingCarts.items.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_product_sku_id: sku.id,
          quantity: 1,
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // 7. Customer creates a wishlist
  const wishlist: IShoppingMallWishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection);
  typia.assert(wishlist);

  // 8. Customer deletes their wishlist
  await api.functional.shoppingMall.customer.wishlists.erase(connection, {
    id: wishlist.id,
  });

  // 9. Attempt to delete again to verify it fails
  await TestValidator.error(
    "Deleting already erased wishlist should fail",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.erase(connection, {
        id: wishlist.id,
      });
    },
  );

  // 10. Register a second different customer
  const customerEmail2: string = typia.random<string & tags.Format<"email">>();
  const customer2: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail2,
        password: "Test1234!",
        nickname: RandomGenerator.name(),
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer2);

  // 11. Switch authentication to customer 2
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail2,
      password: "Test1234!",
      ip: "127.0.0.1",
      href: "http://localhost/login",
      referrer: "http://localhost/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 12. Attempt to delete customer 1's wishlist with customer 2's credentials, expect failure
  await TestValidator.error(
    "Unauthorized wishlist deletion should fail",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.erase(connection, {
        id: wishlist.id,
      });
    },
  );
}

