import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

export async function test_api_product_category_child_creation_under_parent(
  connection: api.IConnection,
) {
  // 1. Admin user joins (authentication)
  const adminFullName = RandomGenerator.name();
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "admin_password_123";

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        full_name: adminFullName,
        email: adminEmail,
        password: adminPassword,
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Admin creates a parent product category
  const parentCategoryName = RandomGenerator.paragraph({
    sentences: 3,
    wordMin: 4,
    wordMax: 10,
  });
  const parentCategoryDescription = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 5,
    sentenceMax: 15,
    wordMin: 3,
    wordMax: 10,
  });
  const parentCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.create(
      connection,
      {
        body: {
          name: parentCategoryName,
          description: parentCategoryDescription,
        } satisfies IShoppingMallProductCategory.ICreate,
      },
    );
  typia.assert(parentCategory);

  // 3. Create a child category under the parent category
  // Ensure child category name is unique among siblings
  const childCategoryName = RandomGenerator.paragraph({
    sentences: 2,
    wordMin: 4,
    wordMax: 10,
  });
  const childCategoryDescription = RandomGenerator.content({
    paragraphs: 1,
    sentenceMin: 3,
    sentenceMax: 10,
    wordMin: 4,
    wordMax: 10,
  });

  const childCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
      connection,
      {
        parentId: parentCategory.id,
        body: {
          name: childCategoryName,
          description: childCategoryDescription,
        } satisfies IShoppingMallProductCategory.ICreate,
      },
    );
  typia.assert(childCategory);

  TestValidator.equals(
    "child category parentId matches parent",
    childCategory.parent_id,
    parentCategory.id,
  );
  TestValidator.equals(
    "child category name matches input",
    childCategory.name,
    childCategoryName,
  );
  TestValidator.predicate(
    "child category id is UUID",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(
      childCategory.id,
    ),
  );
  TestValidator.predicate(
    "child category created_at is ISO string",
    typeof childCategory.created_at === "string" &&
      childCategory.created_at.length > 0,
  );
  TestValidator.predicate(
    "child category updated_at is ISO string",
    typeof childCategory.updated_at === "string" &&
      childCategory.updated_at.length > 0,
  );

  // 4. Attempt to create child category with duplicate name under same parent, expect error
  await TestValidator.error(
    "duplicate child category name should fail",
    async () => {
      await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
        connection,
        {
          parentId: parentCategory.id,
          body: {
            name: childCategoryName,
            description: childCategoryDescription,
          } satisfies IShoppingMallProductCategory.ICreate,
        },
      );
    },
  );

  // 5. Attempt to create child category under non-existent parent, expect error
  await TestValidator.error(
    "create child under non-existent parent should fail",
    async () => {
      await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
        connection,
        {
          parentId: typia.random<string & tags.Format<"uuid">>(),
          body: {
            name: RandomGenerator.paragraph({
              sentences: 2,
              wordMin: 4,
              wordMax: 10,
            }),
            description: RandomGenerator.content({
              paragraphs: 1,
              sentenceMin: 3,
              sentenceMax: 10,
            }),
          } satisfies IShoppingMallProductCategory.ICreate,
        },
      );
    },
  );

  // 6. Attempt to create category without authentication (simulate by using unhashed connection)
  const unauthenticatedConnection: api.IConnection = {
    ...connection,
    headers: {},
  };
  await TestValidator.error(
    "unauthenticated user cannot create child category",
    async () => {
      await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
        unauthenticatedConnection,
        {
          parentId: parentCategory.id,
          body: {
            name: RandomGenerator.paragraph({
              sentences: 2,
              wordMin: 4,
              wordMax: 10,
            }),
            description: RandomGenerator.content({
              paragraphs: 1,
              sentenceMin: 3,
              sentenceMax: 10,
            }),
          } satisfies IShoppingMallProductCategory.ICreate,
        },
      );
    },
  );
}

