import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProduct";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

export async function test_api_product_list_by_customer_with_category_filtering(
  connection: api.IConnection,
) {
  // 1. Register a new customer
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerCreateBody = {
    email: customerEmail,
    password: "StrongPass123!",
    nickname: RandomGenerator.name(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customerAuthorized: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerCreateBody,
    });
  typia.assert(customerAuthorized);

  // 2. Register a new admin
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminCreateBody = {
    email: adminEmail,
    password: "AdminPass456$",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;
  const adminAuthorized: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminCreateBody,
    });
  typia.assert(adminAuthorized);

  // 3. Admin creates product categories
  // Create an array of 3 categories
  const categoryNames = ["Electronics", "Books", "Clothing"];

  // Function to create categories sequentially
  const createdCategories: IShoppingMallProductCategory[] = [];
  for (const name of categoryNames) {
    const categoryBody = {
      name: name,
      description: `Category for ${name}`,
      parent_id: null,
    } satisfies IShoppingMallProductCategory.ICreate;
    const category =
      await api.functional.shoppingMall.admin.productCategories.create(
        connection,
        { body: categoryBody },
      );
    typia.assert(category);
    createdCategories.push(category);
  }

  // 4. Customer login
  const customerLoginBody = {
    email: customerEmail,
    password: "StrongPass123!",
    ip: null,
    href: "https://example.com/login",
    referrer: "https://example.com/home",
  } satisfies IShoppingMallCustomer.ILogin;
  const customerLoggedIn: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.login(connection, {
      body: customerLoginBody,
    });
  typia.assert(customerLoggedIn);

  // 5. Admin login
  const adminLoginBody = {
    email: adminEmail,
    password: "AdminPass456$",
    ip: null,
    href: "https://example.com/admin/login",
    referrer: "https://example.com/admin",
  } satisfies IShoppingMallAdmin.ILogin;
  const adminLoggedIn: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, {
      body: adminLoginBody,
    });
  typia.assert(adminLoggedIn);

  // 6. Customer searches products with category filter
  if (createdCategories.length === 0) {
    throw new Error("No categories created for filtering");
  }

  const categoryToFilter = createdCategories[0];

  const productSearchBody = {
    page: 1,
    limit: 10,
    category_id: categoryToFilter.id,
  } satisfies IShoppingMallProduct.IRequest;

  const productPage: IPageIShoppingMallProduct.ISummary =
    await api.functional.shoppingMall.customer.products.index(connection, {
      body: productSearchBody,
    });
  typia.assert(productPage);

  // 7. Verify pagination data and products
  TestValidator.predicate(
    "pagination.current page is 1",
    productPage.pagination.current === 1,
  );
  TestValidator.predicate(
    "pagination.limit is 10",
    productPage.pagination.limit === 10,
  );
  TestValidator.predicate(
    "products are not empty",
    Array.isArray(productPage.data) && productPage.data.length >= 0,
  );

  if (productPage.data.length > 0) {
    for (const product of productPage.data) {
      TestValidator.predicate(
        "product has non-empty id",
        typeof product.id === "string" && product.id.length > 0,
      );
      TestValidator.predicate(
        "product has non-empty name",
        typeof product.name === "string" && product.name.length > 0,
      );
      TestValidator.predicate(
        "product has non-empty code",
        typeof product.code === "string" && product.code.length > 0,
      );
    }
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import type { IPageIShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallProduct";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";

export async function test_api_product_list_by_seller_with_category_filtering(
  connection: api.IConnection,
) {
  // 1. Seller sign up
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "1234",
        store_name: RandomGenerator.name(),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 2. Admin sign up
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "1234",
        full_name: RandomGenerator.name(),
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 3. Admin creates product categories
  const categories: IShoppingMallProductCategory[] = [];
  for (let i = 0; i < 3; i++) {
    const category: IShoppingMallProductCategory =
      await api.functional.shoppingMall.admin.productCategories.create(
        connection,
        {
          body: {
            name: RandomGenerator.paragraph({
              sentences: 2,
              wordMin: 4,
              wordMax: 8,
            }),
            description: RandomGenerator.content({
              paragraphs: 1,
              sentenceMin: 5,
              sentenceMax: 10,
              wordMin: 4,
              wordMax: 10,
            }),
            parent_id: null,
          } satisfies IShoppingMallProductCategory.ICreate,
        },
      );
    typia.assert(category);
    categories.push(category);
  }

  // 4. Seller logs in again to obtain fresh token
  const sellerLogin: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.login(connection, {
      body: {
        email: sellerEmail,
        password: "1234",
        ip: null,
        href: "https://little.com/shop",
        referrer: "https://little.com",
      } satisfies IShoppingMallSeller.ILogin,
    });
  typia.assert(sellerLogin);

  // 5. Admin logs in again to obtain fresh token
  const adminLogin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, {
      body: {
        email: adminEmail,
        password: "1234",
        ip: null,
        href: "https://little.com/admin",
        referrer: "https://little.com",
      } satisfies IShoppingMallAdmin.ILogin,
    });
  typia.assert(adminLogin);

  // 6. Seller retrieves product list filtered by category
  for (const category of categories) {
    const requestBody = {
      page: 1,
      limit: 10,
      category_id: category.id,
      search_text: undefined,
      brand: undefined,
      include_deleted: false,
    } satisfies IShoppingMallProduct.IRequest;

    const response: IPageIShoppingMallProduct.ISummary =
      await api.functional.shoppingMall.seller.products.index(connection, {
        body: requestBody,
      });

    typia.assert(response);

    // Validate pagination metadata
    TestValidator.predicate(
      "pagination current page is 1",
      response.pagination.current === 1,
    );
    TestValidator.predicate(
      "pagination limit is 10",
      response.pagination.limit === 10,
    );
    TestValidator.predicate(
      "pagination pages and records are non-negative",
      response.pagination.pages >= 0 && response.pagination.records >= 0,
    );

    // Validate each product category matches the filter (category_id)
    // Since IShoppingMallProduct.ISummary has no category info, only id, code, name
    // We will only check the existence of products
    TestValidator.predicate(
      `products list for category ${category.name} is an array`,
      Array.isArray(response.data),
    );
  }
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import type { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";

/**
 * Test detailed customer order retrieval by order code.
 *
 * This test validates the complete workflow where a customer and a seller
 * register, a seller creates a product, the customer places an order with that
 * product, and finally the customer retrieves detailed information of that
 * order via its unique order code.
 *
 * The test ensures:
 *
 * 1. Customer and seller registration with proper authentication.
 * 2. Seller successfully creates a product with mandatory properties.
 * 3. Customer creates an order associating the product SKU with valid quantity.
 * 4. Customer retrieves detailed order data including customer info, order items,
 *    payments, shipment tracking, product reviews, order history,
 *    cancellations, refunds, and return shipments.
 * 5. All returned data is validated for TypeScript type correctness using typia.
 * 6. Proper authorization and user role context switches occur between customer
 *    and seller.
 *
 * Workflow:
 *
 * 1. Seller signup at /auth/seller/join
 * 2. Seller login at /auth/seller/login
 * 3. Create product as seller at /shoppingMall/seller/products
 * 4. Customer signup at /auth/customer/join
 * 5. Customer login at /auth/customer/login
 * 6. Create order with product SKU at /shoppingMall/customer/orders
 * 7. Retrieve detailed order data by order code at
 *    /shoppingMall/customer/orders/{orderCode}
 *
 * This test covers important user journeys including multi-actor
 * authentication, resource creation, order placement, and order detail
 * retrieval.
 */
export async function test_api_order_detail_retrieval_by_customer(
  connection: api.IConnection,
) {
  // 1. Seller signup
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "TestPass123!";
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        store_name: RandomGenerator.name(2),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 2. Seller login for session setup
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      href: "http://localhost/",
      referrer: "http://localhost/start",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates product
  const productCode = RandomGenerator.alphaNumeric(10);
  const productName = RandomGenerator.name(3);
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        code: productCode,
        name: productName,
        description: RandomGenerator.paragraph({ sentences: 5 }),
        brand: RandomGenerator.name(1),
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // Verify SKU presence
  if (
    !product.shopping_mall_product_skus ||
    product.shopping_mall_product_skus.length === 0
  ) {
    throw new Error("Product must have at least one SKU.");
  }

  // Pick the first SKU
  const sku: IShoppingMallProductSku = product.shopping_mall_product_skus[0];
  typia.assert(sku);

  // 4. Customer signup
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "CustPass123!";
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        nickname: RandomGenerator.name(1),
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 5. Customer login for session setup
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      href: "http://localhost/",
      referrer: "http://localhost/start",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 6. Customer places order
  const orderBody: IShoppingMallOrder.ICreate = {
    order_code: RandomGenerator.alphaNumeric(12).toUpperCase(),
    shipping_address: `${RandomGenerator.name(1)}, 1234 Test St, Test City, Test Country`,
    shopping_mall_order_items: [
      {
        shopping_mall_product_sku_id: sku.id,
        quantity: 2,
        unit_price: sku.price,
        total_price: sku.price * 2,
      } satisfies IShoppingMallOrderItem.ICreate,
    ],
  };

  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderBody,
    });
  typia.assert(order);

  // 7. Retrieve order details by orderCode
  const retrievedOrder: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.at(connection, {
      orderCode: order.order_code,
    });
  typia.assert(retrievedOrder);

  // Validate ownership and order code
  TestValidator.equals(
    "retrieved order code matches created order code",
    retrievedOrder.order_code,
    order.order_code,
  );
  TestValidator.equals(
    "retrieved order customer id matches created order customer id",
    retrievedOrder.customer.id,
    customer.id,
  );

  // Validate at least one order item and correctness
  TestValidator.predicate(
    "order has at least one item",
    retrievedOrder.shopping_mall_order_items.length > 0,
  );

  // Validate each order item has required properties
  for (const item of retrievedOrder.shopping_mall_order_items) {
    typia.assert(item);
    TestValidator.predicate(
      "order item belongs to requested order",
      item.shopping_mall_order_id === retrievedOrder.id,
    );
  }

  // Validate payments, shipment tracking, product reviews, etc., are arrays
  TestValidator.predicate(
    "payments array presence",
    Array.isArray(retrievedOrder.shopping_mall_payments),
  );
  TestValidator.predicate(
    "shipment tracking array presence",
    Array.isArray(retrievedOrder.shopping_mall_shipment_trackings),
  );
  TestValidator.predicate(
    "product reviews array presence",
    Array.isArray(retrievedOrder.shopping_mall_product_reviews),
  );
  TestValidator.predicate(
    "order histories array presence",
    Array.isArray(retrievedOrder.shopping_mall_order_histories),
  );
  TestValidator.predicate(
    "order cancellations array presence",
    Array.isArray(retrievedOrder.shopping_mall_order_cancellations),
  );
  TestValidator.predicate(
    "refund requests array presence",
    Array.isArray(retrievedOrder.shopping_mall_refund_requests),
  );
  TestValidator.predicate(
    "return shipments array presence",
    Array.isArray(retrievedOrder.shopping_mall_return_shipments),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallStockAdjustment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallStockAdjustment";

/**
 * Test the complete workflow for deleting a stock adjustment record by its
 * unique ID in the shopping mall platform.
 *
 * This test verifies the entire lifecycle of a stock adjustment from creation
 * to deletion by an admin user. It covers authentication, product and SKU
 * creation, stock adjustment creation, and secure deletion.
 *
 * Steps:
 *
 * 1. Create a new admin user.
 * 2. Login as the admin to obtain access tokens.
 * 3. Create a product.
 * 4. Create a SKU variant for the product.
 * 5. Create a stock adjustment record linked to the SKU.
 * 6. Delete the stock adjustment record by its ID.
 * 7. Attempt to delete the same record again to confirm deletion.
 *
 * This validates admin-only permissions and correct backend behavior for this
 * sensitive operation.
 */
export async function test_api_stock_adjustments_erase_stock_adjustment_by_admin(
  connection: api.IConnection,
) {
  // Step 1-2: Create and authenticate admin user
  const adminEmail = `${RandomGenerator.alphabets(5)}@example.com`;
  const adminJoinBody = {
    email: adminEmail,
    password: "StrongPass123!",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  // Step 3: Create a product
  const productCreateBody = {
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 3,
      wordMax: 8,
    }),
    brand: RandomGenerator.name(),
  } satisfies IShoppingMallProduct.ICreate;

  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.admin.products.create(connection, {
      body: productCreateBody,
    });
  typia.assert(product);
  TestValidator.equals(
    "product code matches",
    product.code,
    productCreateBody.code,
  );

  // Step 4: Create a SKU variant
  const skuCreateBody = {
    sku_code: RandomGenerator.alphaNumeric(10),
    price: Number((Math.random() * 1000 + 10).toFixed(2)),
    attributes_json: JSON.stringify({ color: "red", size: "M" }),
  } satisfies IShoppingMallProductSku.ICreate;

  const sku: IShoppingMallProductSku =
    await api.functional.shoppingMall.admin.products.skus.createSku(
      connection,
      { productCode: product.code, body: skuCreateBody },
    );
  typia.assert(sku);
  TestValidator.equals(
    "sku code matches",
    sku.sku_code,
    skuCreateBody.sku_code,
  );

  // Step 5: Create a stock adjustment record
  const stockAdjustmentCreateBody = {
    shopping_mall_product_sku_id: sku.id,
    adjustment_type: "addition",
    quantity: 100,
    actor_type: "admin",
    actor_id: admin.id,
  } satisfies IShoppingMallStockAdjustment.ICreate;

  const stockAdjustment: IShoppingMallStockAdjustment =
    await api.functional.shoppingMall.admin.stockAdjustments.create(
      connection,
      { body: stockAdjustmentCreateBody },
    );
  typia.assert(stockAdjustment);
  TestValidator.equals(
    "stock adjustment sku id matches",
    stockAdjustment.shopping_mall_product_sku_id,
    sku.id,
  );

  // Step 6: Delete the stock adjustment record by id
  await api.functional.shoppingMall.admin.stockAdjustments.eraseStockAdjustment(
    connection,
    { id: stockAdjustment.id },
  );

  // Step 7: Attempt to delete the same record again, expecting error
  await TestValidator.error(
    "deleting non-existent stock adjustment should fail",
    async () => {
      await api.functional.shoppingMall.admin.stockAdjustments.eraseStockAdjustment(
        connection,
        { id: stockAdjustment.id },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
