/**
 * Validate updating shipment tracking by an admin user.
 *
 * This test performs the following steps:
 *
 * 1. Admin joins and logs in to obtain authentication.
 * 2. Seller joins and logs in to create product.
 * 3. Customer joins and logs in to place an order.
 * 4. Admin creates shipment tracking linked to the order.
 * 5. Admin updates the shipment tracking record's details.
 * 6. Validates that all updated fields are correctly reflected.
 * 7. Tests the unauthorized access attempt by non-admin user.
 */
export async function test_api_admin_shipment_tracking_update_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin join
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: "admin-password",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  // 2. Admin login (redundant because join sets token, but per scenario)
  const adminLoginBody = {
    email: adminEmail,
    password: "admin-password",
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com",
  } satisfies IShoppingMallAdmin.ILogin;
  const adminLogin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, { body: adminLoginBody });
  typia.assert(adminLogin);

  // 3. Seller join and login
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerJoinBody = {
    email: sellerEmail,
    password: "seller-password",
    store_name: RandomGenerator.name(),
  } satisfies IShoppingMallSeller.ICreate;
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerJoinBody });
  typia.assert(seller);

  const sellerLoginBody = {
    email: sellerEmail,
    password: "seller-password",
    href: "https://seller.example.com/login",
    referrer: "https://seller.example.com",
  } satisfies IShoppingMallSeller.ILogin;
  const sellerLogin: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.login(connection, {
      body: sellerLoginBody,
    });
  typia.assert(sellerLogin);

  // 4. Customer join and login
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerJoinBody = {
    email: customerEmail,
    password: "customer-password",
    nickname: RandomGenerator.name(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerJoinBody,
    });
  typia.assert(customer);

  const customerLoginBody = {
    email: customerEmail,
    password: "customer-password",
    href: "https://customer.example.com/login",
    referrer: "https://customer.example.com",
  } satisfies IShoppingMallCustomer.ILogin;
  const customerLogin: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.login(connection, {
      body: customerLoginBody,
    });
  typia.assert(customerLogin);

  // 5. Seller creates product
  const productCreateBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 3 }),
    brand: RandomGenerator.name(1),
  } satisfies IShoppingMallProduct.ICreate;
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: productCreateBody,
    });
  typia.assert(product);

  // 6. Customer places order with items referencing product SKU
  // Since SKU creation or fetching is not provided, simulate by using product id as SKU id for order creation
  if (
    product.shopping_mall_product_skus === undefined ||
    product.shopping_mall_product_skus.length === 0
  ) {
    throw new Error("Product has no SKUs for order item");
  }
  const sku = product.shopping_mall_product_skus[0];

  const orderCreateBody = {
    order_code: `ORD-${RandomGenerator.alphaNumeric(8)}`,
    shipping_address: "123 Main St, Seoul, South Korea",
    shopping_mall_order_items: [
      {
        shopping_mall_product_sku_id: sku.id,
        quantity: 1,
        unit_price: sku.price,
        total_price: sku.price,
      },
    ],
  } satisfies IShoppingMallOrder.ICreate;
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderCreateBody,
    });
  typia.assert(order);

  // 7. Admin creates shipment tracking for the order
  const shipmentTrackingCreateBody = {
    shopping_mall_order_id: order.id,
    tracking_number: "TRACK123456789",
    carrier_name: "FedEx",
    shipping_status: "shipped",
    shipped_at: new Date().toISOString(),
    delivered_at: null,
  } satisfies IShoppingMallShipmentTracking.ICreate;
  const shipmentTracking: IShoppingMallShipmentTracking =
    await api.functional.shoppingMall.admin.shipmentTrackings.create(
      connection,
      { body: shipmentTrackingCreateBody },
    );
  typia.assert(shipmentTracking);

  // 8. Admin updates the shipment tracking
  // update with new tracking information
  const updatedTrackingNumber = "TRACK987654321";
  const updatedCarrierName = "DHL";
  const updatedShippingStatus = "in_transit";
  const updatedShippedAt = new Date(Date.now() - 3600000).toISOString(); // 1 hour ago
  const updatedDeliveredAt = new Date(Date.now() + 3600000).toISOString(); // an hour later

  const shipmentTrackingUpdateBody = {
    tracking_number: updatedTrackingNumber,
    carrier_name: updatedCarrierName,
    shipping_status: updatedShippingStatus,
    shipped_at: updatedShippedAt,
    delivered_at: updatedDeliveredAt,
  } satisfies IShoppingMallShipmentTracking.IUpdate;

  const updatedShipmentTracking: IShoppingMallShipmentTracking =
    await api.functional.shoppingMall.admin.shipmentTrackings.updateShipmentTracking(
      connection,
      {
        id: shipmentTracking.id,
        body: shipmentTrackingUpdateBody,
      },
    );
  typia.assert(updatedShipmentTracking);

  // Validate updated fields
  TestValidator.equals(
    "Updated tracking number",
    updatedShipmentTracking.tracking_number,
    updatedTrackingNumber,
  );
  TestValidator.equals(
    "Updated carrier name",
    updatedShipmentTracking.carrier_name,
    updatedCarrierName,
  );
  TestValidator.equals(
    "Updated shipping status",
    updatedShipmentTracking.shipping_status,
    updatedShippingStatus,
  );
  TestValidator.equals(
    "Updated shipped at",
    updatedShipmentTracking.shipped_at,
    updatedShippedAt,
  );
  TestValidator.equals(
    "Updated delivered at",
    updatedShipmentTracking.delivered_at,
    updatedDeliveredAt,
  );

  // 9. Verify unauthorized update attempt by customer
  // Switch context to customer to test forbidden update
  await api.functional.auth.customer.login(connection, {
    body: customerLoginBody,
  });

  await TestValidator.error(
    "Non-admin user cannot update shipment tracking",
    async () => {
      await api.functional.shoppingMall.admin.shipmentTrackings.updateShipmentTracking(
        connection,
        {
          id: shipmentTracking.id,
          body: shipmentTrackingUpdateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import type { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";

/**
 * Validates the retrieval of detailed order item information by a seller.
 *
 * This test encompasses the complete workflow of creating seller and customer
 * users, creating products and product SKU variants, placing an order by the
 * customer, adding order items by the seller, and finally retrieving the
 * detailed data of the order item.
 *
 * Steps:
 *
 * 1. Seller registration and authentication
 * 2. Product creation by seller
 * 3. SKU variant creation for the product
 * 4. Customer registration and authentication
 * 5. Customer creates an order referencing the product SKUs
 * 6. Seller adds an order item to the order
 * 7. Seller retrieves detailed order item info by orderCode and itemId
 * 8. Assertion to ensure retrieved data matches the created order item
 */
export async function test_api_order_item_detailed_retrieval_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller registration
  const sellerCreationBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password123!",
    store_name: RandomGenerator.name(),
  } satisfies IShoppingMallSeller.ICreate;
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: sellerCreationBody,
    });
  typia.assert(seller);

  // 2. Seller login (dynamic authentication for multiple actor switching)
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerCreationBody.email,
      password: "Password123!",
      ip: null,
      href: "https://localhost/login",
      referrer: "https://localhost/",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Create a product by the seller
  const alphaNumericCode = RandomGenerator.alphaNumeric(10);
  const productCreationBody = {
    code: alphaNumericCode,
    name: RandomGenerator.name(),
    description: RandomGenerator.paragraph({ sentences: 5 }),
    brand: RandomGenerator.name(),
  } satisfies IShoppingMallProduct.ICreate;
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: productCreationBody,
    });
  typia.assert(product);

  // 4. Create SKU variants for the product
  const sku1Body = {
    sku_code: RandomGenerator.alphaNumeric(8),
    price: 15000,
    attributes_json: JSON.stringify({ color: "red", size: "M" }),
  } satisfies IShoppingMallProductSku.ICreate;
  const sku1: IShoppingMallProductSku =
    await api.functional.shoppingMall.seller.products.skus.createSku(
      connection,
      {
        productCode: productCreationBody.code,
        body: sku1Body,
      },
    );
  typia.assert(sku1);

  const sku2Body = {
    sku_code: RandomGenerator.alphaNumeric(8),
    price: 25000,
    attributes_json: JSON.stringify({ color: "blue", size: "L" }),
  } satisfies IShoppingMallProductSku.ICreate;
  const sku2: IShoppingMallProductSku =
    await api.functional.shoppingMall.seller.products.skus.createSku(
      connection,
      {
        productCode: productCreationBody.code,
        body: sku2Body,
      },
    );
  typia.assert(sku2);

  // 5. Customer registration
  const customerCreationBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "Password456!",
    nickname: RandomGenerator.name(),
  } satisfies IShoppingMallCustomer.ICreate;
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerCreationBody,
    });
  typia.assert(customer);

  // 6. Customer login (actor switching)
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerCreationBody.email,
      password: "Password456!",
      ip: null,
      href: "https://localhost/login",
      referrer: "https://localhost/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 7. Customer creates an order
  const orderCode = RandomGenerator.alphaNumeric(12);
  const orderCreateBody = {
    order_code: orderCode,
    shipping_address: RandomGenerator.paragraph({ sentences: 3 }),
    shopping_mall_order_items: [],
  } satisfies IShoppingMallOrder.ICreate;
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderCreateBody,
    });
  typia.assert(order);

  // 8. Switch back to seller auth
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerCreationBody.email,
      password: "Password123!",
      ip: null,
      href: "https://localhost/login",
      referrer: "https://localhost/",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 9. Seller adds an order item referencing sku1
  const orderItemCreateBody = {
    shopping_mall_product_sku_id: sku1.id,
    quantity: 2,
    unit_price: sku1.price,
    total_price: sku1.price * 2,
  } satisfies IShoppingMallOrderItem.ICreate;
  const createdOrderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.seller.orders.items.create(connection, {
      orderCode: orderCode,
      body: orderItemCreateBody,
    });
  typia.assert(createdOrderItem);

  // 10. Seller retrieves detailed order item info by orderCode and itemId
  const retrievedOrderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.seller.orders.items.at(connection, {
      orderCode: orderCode,
      itemId: createdOrderItem.id,
    });
  typia.assert(retrievedOrderItem);

  // 11. Assert that retrieved data matches created order item
  TestValidator.equals(
    "Retrieved order item matches created order item",
    retrievedOrderItem,
    createdOrderItem,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import type { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";

/**
 * Validate administrator's ability to retrieve detailed information for a
 * specific order item by its order code and item ID.
 *
 * This test executes a multi-actor scenario involving administrator, seller,
 * and customer roles within a shopping mall system. The workflow includes:
 *
 * 1. Admin user account registration and login
 * 2. Seller user registration and login
 * 3. Customer user registration and login
 * 4. Seller creates a new product
 * 5. Seller adds SKU variants to the product
 * 6. Customer places an order with the SKU
 * 7. Admin adds an order item to the customer's order
 * 8. Admin retrieves detailed information about the order item
 *
 * The test verifies that:
 *
 * - Authentication tokens are properly issued and switched between actors.
 * - Product and SKU creation use valid data following DTO constraints.
 * - Customer order creation includes proper order data.
 * - Order item creation associates the item with correct SKU and quantity.
 * - Admin retrieval returns the correct order item details matching the created
 *   item.
 *
 * @param connection HTTP connection instance used to call APIs
 */
export async function test_api_order_item_detailed_retrieval_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins and logs in, getting admin authorization token
  const adminJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "AdminTest123!",
    full_name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.IJoin;
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(admin);

  const adminLoginBody = {
    email: adminJoinBody.email,
    password: adminJoinBody.password,
    ip: null,
    href: "https://admin.login.test/",
    referrer: "https://admin.referrer.test/",
  } satisfies IShoppingMallAdmin.ILogin;
  const adminLoggedIn: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, { body: adminLoginBody });
  typia.assert(adminLoggedIn);

  // 2. Seller joins and logs in
  const sellerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "SellerTest123!",
    store_name: RandomGenerator.name(2),
  } satisfies IShoppingMallSeller.ICreate;
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, { body: sellerJoinBody });
  typia.assert(seller);

  const sellerLoginBody = {
    email: sellerJoinBody.email,
    password: sellerJoinBody.password,
    ip: null,
    href: "https://seller.login.test/",
    referrer: "https://seller.referrer.test/",
  } satisfies IShoppingMallSeller.ILogin;
  const sellerLoggedIn: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.login(connection, {
      body: sellerLoginBody,
    });
  typia.assert(sellerLoggedIn);

  // 3. Customer joins and logs in
  const customerJoinBody = {
    email: typia.random<string & tags.Format<"email">>(),
    password: "CustomerTest123!",
    nickname: RandomGenerator.name(1),
  } satisfies IShoppingMallCustomer.ICreate;
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: customerJoinBody,
    });
  typia.assert(customer);

  const customerLoginBody = {
    email: customerJoinBody.email,
    password: customerJoinBody.password,
    href: "https://customer.login.test/",
    referrer: "https://customer.referrer.test/",
  } satisfies IShoppingMallCustomer.ILogin;
  const customerLoggedIn: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.login(connection, {
      body: customerLoginBody,
    });
  typia.assert(customerLoggedIn);

  // 4. Seller creates a product
  // Switch to seller authentication token
  await api.functional.auth.seller.login(connection, { body: sellerLoginBody });

  const productCreateBody = {
    code: RandomGenerator.alphaNumeric(10),
    name: RandomGenerator.name(2),
    description: RandomGenerator.paragraph({
      sentences: 5,
      wordMin: 3,
      wordMax: 7,
    }),
    brand: RandomGenerator.name(1),
  } satisfies IShoppingMallProduct.ICreate;
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: productCreateBody,
    });
  typia.assert(product);

  // 5. Seller adds SKU to the product
  const skuCreateBody = {
    sku_code: RandomGenerator.alphaNumeric(8),
    price: typia.random<
      number & tags.Type<"uint32"> & tags.Minimum<100> & tags.Maximum<100000>
    >(),
    attributes_json: JSON.stringify({ color: "Red", size: "M" }),
  } satisfies IShoppingMallProductSku.ICreate;
  const sku: IShoppingMallProductSku =
    await api.functional.shoppingMall.seller.products.skus.createSku(
      connection,
      { productCode: product.code, body: skuCreateBody },
    );
  typia.assert(sku);

  // 6. Customer places an order
  // Switch to customer authentication token
  await api.functional.auth.customer.login(connection, {
    body: customerLoginBody,
  });

  const orderCreateBody: IShoppingMallOrder.ICreate = {
    order_code: RandomGenerator.alphaNumeric(12),
    shipping_address: `${RandomGenerator.name(1)} street, City, Country`,
    shopping_mall_order_items: [],
  };
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderCreateBody,
    });
  typia.assert(order);

  // 7. Admin adds an order item
  // Switch to admin authentication token
  await api.functional.auth.admin.login(connection, { body: adminLoginBody });

  const orderItemCreateBody = {
    shopping_mall_product_sku_id: sku.id,
    quantity: 2,
    unit_price: skuCreateBody.price,
    total_price: skuCreateBody.price * 2,
  } satisfies IShoppingMallOrderItem.ICreate;

  const orderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.admin.orders.items.create(connection, {
      orderCode: order.order_code,
      body: orderItemCreateBody,
    });
  typia.assert(orderItem);

  // 8. Admin retrieves detailed information for the order item
  const retrievedOrderItem: IShoppingMallOrderItem =
    await api.functional.shoppingMall.admin.orders.items.at(connection, {
      orderCode: order.order_code,
      itemId: orderItem.id,
    });
  typia.assert(retrievedOrderItem);

  // Validate that retrieved item matches the created order item
  TestValidator.equals(
    "Order item ID should match",
    retrievedOrderItem.id,
    orderItem.id,
  );
  TestValidator.equals(
    "Order item SKU ID should match",
    retrievedOrderItem.shopping_mall_product_sku_id,
    orderItem.shopping_mall_product_sku_id,
  );
  TestValidator.equals(
    "Order item quantity should match",
    retrievedOrderItem.quantity,
    orderItem.quantity,
  );
  TestValidator.equals(
    "Order item unit price should match",
    retrievedOrderItem.unit_price,
    orderItem.unit_price,
  );
  TestValidator.equals(
    "Order item total price should match",
    retrievedOrderItem.total_price,
    orderItem.total_price,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
