import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallChannelDefinition } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallChannelDefinition";

/**
 * Test updating an existing child channel under a parent channel as an admin
 * user.
 *
 * This test covers:
 *
 * 1. Admin registration and authentication
 * 2. Creating a parent shopping mall channel
 * 3. Creating a child channel under the parent
 * 4. Updating the child channel's name and optional description
 * 5. Validating the update's success and data consistency
 *
 * Each step asserts the response type with typia.assert, and validates business
 * logic constraints using TestValidator for strict correctness.
 */
export async function test_api_shopping_mall_admin_channels_children_update_child_channel(
  connection: api.IConnection,
) {
  // 1. Admin registration and join
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminJoinBody = {
    email: adminEmail,
    password: "admin-password-123",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: adminJoinBody,
    });
  typia.assert(admin);

  TestValidator.predicate(
    "admin authorization token exists",
    typeof admin.token.access === "string" && admin.token.access.length > 0,
  );

  // 2. Create a parent channel
  const parentChannelCode = `parent_${RandomGenerator.alphabets(6)}`;
  const parentChannelCreateBody = {
    channel_code: parentChannelCode,
    channel_name: RandomGenerator.name(2),
    description: "Parent channel for testing",
  } satisfies IShoppingMallChannelDefinition.ICreate;

  const parentChannel: IShoppingMallChannelDefinition =
    await api.functional.shoppingMall.admin.channels.create(connection, {
      body: parentChannelCreateBody,
    });
  typia.assert(parentChannel);
  TestValidator.equals(
    "parent channel code matches",
    parentChannel.channel_code,
    parentChannelCode,
  );

  // 3. Create a child channel under the parent
  const childChannelCode = `child_${RandomGenerator.alphabets(6)}`;
  const childChannelCreateBody = {
    parent_channel_id: parentChannel.id,
    channel_code: childChannelCode,
    channel_name: RandomGenerator.name(2),
    description: "Child channel created for update test",
  } satisfies IShoppingMallChannelDefinition.ICreate;

  const childChannel: IShoppingMallChannelDefinition =
    await api.functional.shoppingMall.admin.channels.children.create(
      connection,
      {
        channelCode: parentChannelCode,
        body: childChannelCreateBody,
      },
    );
  typia.assert(childChannel);
  TestValidator.equals(
    "child channel code matches",
    childChannel.channel_code,
    childChannelCode,
  );
  TestValidator.equals(
    "child channel parent id matches",
    childChannel.parent_channel_id,
    parentChannel.id,
  );

  // 4. Update the child channel (name and optionally description)
  const updatedName = RandomGenerator.name(3);
  const updatedDescription = "Updated description for child channel";
  const updateBody = {
    channel_code: childChannelCode, // required immutable code
    channel_name: updatedName,
    description: updatedDescription,
  } satisfies IShoppingMallChannelDefinition.IUpdate;

  const updatedChannel: IShoppingMallChannelDefinition =
    await api.functional.shoppingMall.admin.channels.children.updateChildChannel(
      connection,
      {
        channelCode: parentChannelCode,
        childChannelCode: childChannelCode,
        body: updateBody,
      },
    );
  typia.assert(updatedChannel);

  // 5. Validate the update
  TestValidator.equals(
    "updated channel code remains same",
    updatedChannel.channel_code,
    childChannelCode,
  );
  TestValidator.equals(
    "updated channel name is correct",
    updatedChannel.channel_name,
    updatedName,
  );
  TestValidator.equals(
    "updated channel description is correct",
    updatedChannel.description,
    updatedDescription,
  );

  TestValidator.notEquals(
    "channel name changed from original",
    childChannel.channel_name,
    updatedChannel.channel_name,
  );

  TestValidator.notEquals(
    "channel description changed from original",
    childChannel.description,
    updatedChannel.description,
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

export async function test_api_product_category_child_update_by_admin(
  connection: api.IConnection,
) {
  // Admin join for authenticated operations
  const adminEmail: string = typia.random<string & tags.Format<"email">>();
  const adminPassword = "AdminPass123!";
  const adminJoinBody = {
    email: adminEmail,
    password: adminPassword,
    full_name: RandomGenerator.name(2),
  } satisfies IShoppingMallAdmin.IJoin;

  const adminAuthorized: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminJoinBody });
  typia.assert(adminAuthorized);

  // Create parent product category
  const parentCategoryCreateBody = {
    name: `Category-${RandomGenerator.paragraph({ sentences: 2, wordMin: 5, wordMax: 8 })}`,
    description: RandomGenerator.content({ paragraphs: 1 }),
    parent_id: null,
  } satisfies IShoppingMallProductCategory.ICreate;

  const parentCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.create(
      connection,
      { body: parentCategoryCreateBody },
    );
  typia.assert(parentCategory);

  // Create first child product category
  const childCategoryName1 = `Child-${RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 7 })}`;
  const childCategoryCreateBody1 = {
    name: childCategoryName1,
    description: RandomGenerator.content({ paragraphs: 1 }),
    parent_id: parentCategory.id,
  } satisfies IShoppingMallProductCategory.ICreate;

  const childCategory1: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
      connection,
      { parentId: parentCategory.id, body: childCategoryCreateBody1 },
    );
  typia.assert(childCategory1);

  // Create second child product category for uniqueness conflict test
  const childCategoryName2 = `Child-${RandomGenerator.paragraph({ sentences: 2, wordMin: 4, wordMax: 7 })}`;
  const childCategoryCreateBody2 = {
    name: childCategoryName2,
    description: RandomGenerator.content({ paragraphs: 1 }),
    parent_id: parentCategory.id,
  } satisfies IShoppingMallProductCategory.ICreate;

  const childCategory2: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
      connection,
      { parentId: parentCategory.id, body: childCategoryCreateBody2 },
    );
  typia.assert(childCategory2);

  // Update the first child category
  const updatedName = `Updated-${RandomGenerator.paragraph({ sentences: 2, wordMin: 5, wordMax: 10 })}`;
  const updatedDescription = RandomGenerator.content({ paragraphs: 2 });

  const updateBody = {
    name: updatedName,
    description: updatedDescription,
    parent_id: parentCategory.id,
  } satisfies IShoppingMallProductCategory.IUpdate;

  const updatedCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.children.updateChildCategory(
      connection,
      {
        parentId: parentCategory.id,
        childId: childCategory1.id,
        body: updateBody,
      },
    );
  typia.assert(updatedCategory);

  TestValidator.equals(
    "updated category name",
    updatedCategory.name,
    updatedName,
  );
  TestValidator.equals(
    "updated category description",
    updatedCategory.description,
    updatedDescription,
  );

  TestValidator.predicate(
    "updated_at later than created_at",
    new Date(updatedCategory.updated_at).getTime() >
      new Date(updatedCategory.created_at).getTime(),
  );

  // Validate uniqueness violation: try to update first child to second child's name
  await TestValidator.error("duplicate sibling name validation", async () => {
    const conflictUpdateBody: IShoppingMallProductCategory.IUpdate = {
      name: childCategoryName2,
      description: RandomGenerator.content({ paragraphs: 1 }),
      parent_id: parentCategory.id,
    };
    await api.functional.shoppingMall.admin.productCategories.children.updateChildCategory(
      connection,
      {
        parentId: parentCategory.id,
        childId: childCategory1.id,
        body: conflictUpdateBody,
      },
    );
  });

  // Validate unauthorized update
  const unauthConn: api.IConnection = { ...connection, headers: {} };
  await TestValidator.error("unauthorized update fails", async () => {
    const illegalUpdateBody = {
      name: `IllegalUpdate-${RandomGenerator.paragraph({ sentences: 1 })}`,
      description: null,
      parent_id: parentCategory.id,
    } satisfies IShoppingMallProductCategory.IUpdate;

    await api.functional.shoppingMall.admin.productCategories.children.updateChildCategory(
      unauthConn,
      {
        parentId: parentCategory.id,
        childId: childCategory1.id,
        body: illegalUpdateBody,
      },
    );
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";

/**
 * This test verifies that an authenticated admin can delete a child product
 * category under a specified parent category.
 *
 * It performs the following steps:
 *
 * 1. Registers a new admin user through the join endpoint.
 * 2. Creates a parent product category.
 * 3. Creates a child product category under the parent.
 * 4. Calls the delete API to delete the child category by parentId and childId.
 * 5. Verifies the child category deletion by asserting deletion success and that
 *    the category cannot be retrieved.
 * 6. Checks that deletion permission enforcement prevents non-admin from deleting.
 */
export async function test_api_product_category_child_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: "AdminPass123!",
        full_name: "Admin User",
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  // 2. Create a parent category
  const parentCategoryBody = {
    parent_id: null,
    name: `Category-${RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 })}`,
    description: "Parent category description",
  } satisfies IShoppingMallProductCategory.ICreate;

  const parentCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.create(
      connection,
      { body: parentCategoryBody },
    );
  typia.assert(parentCategory);

  // 3. Create a child category
  const childCategoryBody = {
    parent_id: parentCategory.id,
    name: `Child-${RandomGenerator.paragraph({ sentences: 2, wordMin: 3, wordMax: 8 })}`,
    description: "Child category description",
  } satisfies IShoppingMallProductCategory.ICreate;

  const childCategory: IShoppingMallProductCategory =
    await api.functional.shoppingMall.admin.productCategories.children.createChildCategory(
      connection,
      {
        parentId: parentCategory.id,
        body: childCategoryBody,
      },
    );
  typia.assert(childCategory);

  TestValidator.equals(
    "Parent and child parent_id link",
    childCategory.parent_id,
    parentCategory.id,
  );

  // 4. Delete the child category
  await api.functional.shoppingMall.admin.productCategories.children.erase(
    connection,
    {
      parentId: parentCategory.id,
      childId: childCategory.id,
    },
  );

  // 5. Verify the child category cannot be fetched (assuming fetch endpoint exists)
  // Since fetch endpoint is not given, we verify indirectly by error check
  // Try deletion again should error
  await TestValidator.error(
    "Deleting non-existent child category should fail",
    async () => {
      await api.functional.shoppingMall.admin.productCategories.children.erase(
        connection,
        {
          parentId: parentCategory.id,
          childId: childCategory.id,
        },
      );
    },
  );
}

