import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallUserRole } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallUserRole";

/**
 * This test function validates the user role assignment functionality by an
 * admin user in a shopping mall platform. It creates an admin user via the
 * /auth/admin/join endpoint to establish proper authorization context. It then
 * assigns the 'admin' role to a user with a known valid UUID representing an
 * existing user. The test verifies correct creation of the role assignment,
 * validates all returned properties, and confirms that duplicate role
 * assignment causes an error.
 */
export async function test_api_user_role_creation_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin user creation
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.auth.admin.join(connection, {
    body: {
      email: adminEmail,
      password: "StrongPassword123!",
      full_name: RandomGenerator.name(),
    } satisfies IShoppingMallAdmin.IJoin,
  });
  typia.assert(admin);

  // 2. Assign user role
  // Use fixed valid UUID to simulate existing user
  const userId = "00000000-0000-0000-0000-000000000001";
  const roleName = "admin";

  // Create role for this user
  const userRole = await api.functional.shoppingMall.admin.userRoles.create(
    connection,
    {
      body: {
        user_id: userId,
        role_name: roleName,
      } satisfies IShoppingMallUserRole.ICreate,
    },
  );
  typia.assert(userRole);

  TestValidator.predicate(
    "userRole.id is uuid",
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(
      userRole.id,
    ),
  );
  TestValidator.equals("userRole.user_id matches", userRole.user_id, userId);
  TestValidator.equals(
    "userRole.role_name matches",
    userRole.role_name,
    roleName,
  );
  TestValidator.predicate(
    "userRole.created_at is ISO string",
    !Number.isNaN(Date.parse(userRole.created_at)),
  );
  TestValidator.predicate(
    "userRole.updated_at is ISO string",
    !Number.isNaN(Date.parse(userRole.updated_at)),
  );

  // 3. Duplicate role assignment should fail
  await TestValidator.error(
    "duplicate role assignment should fail",
    async () => {
      await api.functional.shoppingMall.admin.userRoles.create(connection, {
        body: {
          user_id: userId,
          role_name: roleName,
        } satisfies IShoppingMallUserRole.ICreate,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
