import type { IShoppingMallWishlist } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlist";
import type { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";

export async function test_api_customer_wishlist_item_erase(
  connection: api.IConnection,
) {
  // 1. Register a new seller account
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const seller = await api.functional.auth.seller.join(connection, {
    body: {
      email: sellerEmail,
      password: "1234",
      store_name: RandomGenerator.name(),
    } satisfies IShoppingMallSeller.ICreate,
  });
  typia.assert(seller);

  // 2. Seller login to authenticate
  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: "1234",
      ip: null,
      href: "https://example.com/login",
      referrer: "https://example.com",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates a new product
  const productCode = RandomGenerator.alphaNumeric(12);
  const product = await api.functional.shoppingMall.seller.products.create(
    connection,
    {
      body: {
        code: productCode,
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 5 }),
        brand: RandomGenerator.name(1),
      } satisfies IShoppingMallProduct.ICreate,
    },
  );
  typia.assert(product);

  // 4. Seller creates SKUs for the product
  const sku1 = await api.functional.shoppingMall.seller.products.skus.createSku(
    connection,
    {
      productCode: productCode,
      body: {
        sku_code: productCode + "-RED",
        price: 10000,
        attributes_json: JSON.stringify({ color: "red", size: "M" }),
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku1);

  const sku2 = await api.functional.shoppingMall.seller.products.skus.createSku(
    connection,
    {
      productCode: productCode,
      body: {
        sku_code: productCode + "-BLU",
        price: 11000,
        attributes_json: JSON.stringify({ color: "blue", size: "L" }),
      } satisfies IShoppingMallProductSku.ICreate,
    },
  );
  typia.assert(sku2);

  // 5. Register a new customer account
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customer = await api.functional.auth.customer.join(connection, {
    body: {
      email: customerEmail,
      password: "1234",
      nickname: RandomGenerator.name(),
    } satisfies IShoppingMallCustomer.ICreate,
  });
  typia.assert(customer);

  // 6. Customer login to authenticate properly and get session
  const customerAuthorized = await api.functional.auth.customer.login(
    connection,
    {
      body: {
        email: customerEmail,
        password: "1234",
        ip: null,
        href: "https://example.com/customer-login",
        referrer: "https://example.com",
      } satisfies IShoppingMallCustomer.ILogin,
    },
  );
  typia.assert(customerAuthorized);

  // 7. Customer creates a shopping cart with real session ID
  // Note: session id is shopping_mall_customer_session_id, not available directly
  // We'll use customerAuthorized.token.refreshable_until for time, so here we set placeholder
  // to simulate this, since no direct method to get session id is provided in API, omit session id
  // But the create API requires it, so let's just use the active customer ID instead for both (even though not perfect)

  // We will create a dummy session id string with UUID format to fulfill type
  const sessionId = typia.random<string & tags.Format<"uuid">>();

  const cart = await api.functional.shoppingMall.customer.shoppingCarts.create(
    connection,
    {
      body: {
        shopping_mall_customer_id: customerAuthorized.id,
        shopping_mall_customer_session_id: sessionId,
      } satisfies IShoppingMallShoppingCart.ICreate,
    },
  );
  typia.assert(cart);

  // 8. Customer adds an item to the shopping cart using sku1
  const cartItem =
    await api.functional.shoppingMall.customer.shoppingCarts.items.create(
      connection,
      {
        cartId: cart.id,
        body: {
          shopping_mall_product_sku_id: sku1.id,
          quantity: 1,
        } satisfies IShoppingMallCartItem.ICreate,
      },
    );
  typia.assert(cartItem);

  // 9. Customer creates a wishlist
  const wishlist =
    await api.functional.shoppingMall.customer.wishlists.create(connection);
  typia.assert(wishlist);

  // 10. Customer adds sku1 to the wishlist
  const wishlistItem =
    await api.functional.shoppingMall.customer.wishlists.items.create(
      connection,
      {
        wishlistId: wishlist.id,
        body: {
          shopping_mall_product_sku_id: sku1.id,
          quantity: 1,
          shopping_mall_wishlist_id: wishlist.id,
        } satisfies IShoppingMallWishlistItem.ICreate,
      },
    );
  typia.assert(wishlistItem);

  // 11. Erase the wishlist item
  await api.functional.shoppingMall.customer.wishlists.items.eraseWishlistItem(
    connection,
    {
      wishlistId: wishlist.id,
      itemId: wishlistItem.id,
    },
  );

  // 12. Validate that the wishlist item is deleted by attempting to delete it again, expecting an error
  await TestValidator.error(
    "Deleting already deleted wishlist item should fail",
    async () => {
      await api.functional.shoppingMall.customer.wishlists.items.eraseWishlistItem(
        connection,
        {
          wishlistId: wishlist.id,
          itemId: wishlistItem.id,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import type { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";

/**
 * Validate the ability for seller to update shipment tracking.
 *
 * This test follows the full lifecycle of a seller creating an account,
 * creating a product, a customer placing an order for that product, seller
 * creating shipment tracking, and seller updating it. Ensures authentication,
 * authorization, data flow, type safety, and business validation.
 *
 * Steps
 *
 * 1. Seller signs up and authenticates.
 * 2. Seller creates a new product.
 * 3. Customer signs up and authenticates.
 * 4. Customer places an order for the product.
 * 5. Seller creates a shipment tracking record for the order.
 * 6. Seller updates the shipment tracking record with new shipment details.
 * 7. Validate the update response matches expected values.
 * 8. Validate the persistence of updated shipment tracking.
 * 9. Validates unauthorized access is prevented.
 */
export async function test_api_shipment_tracking_update_by_seller(
  connection: api.IConnection,
) {
  // 1. Seller sign up and authentication
  const sellerEmail: string = typia.random<string & tags.Format<"email">>();
  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: "TestPass1234!",
        store_name: "Test Seller Store",
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  // 2. Seller creates a product
  const productCode = RandomGenerator.alphaNumeric(10);
  const productName = RandomGenerator.name(2);
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        code: productCode,
        name: productName,
        description: "Test product description",
        brand: "Test Brand",
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // 3. Customer sign up and authentication
  const customerEmail: string = typia.random<string & tags.Format<"email">>();
  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: "CustPass1234!",
        nickname: "TestCustomer",
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  // 4. Customer places an order for the product
  // Assuming product has one SKU, create an order with that SKU.
  // If no SKUs, then the productSkuId must be set to product id for test.
  const productSkuId = product.shopping_mall_product_skus?.length
    ? product.shopping_mall_product_skus[0].id
    : product.id;
  const orderCreateBody = {
    order_code: `ORD-${Date.now()}`,
    shipping_address: "123 Test Street, Test City",
    shopping_mall_order_items: [
      {
        shopping_mall_product_sku_id: productSkuId,
        quantity: 1,
        unit_price: 100,
        total_price: 100,
      },
    ],
    shopping_mall_payments: [
      {
        shopping_mall_order_id: "00000000-0000-0000-0000-000000000000", // will be ignored on create
        payment_method: "credit_card",
        payment_status: "completed",
        payment_amount: 100,
        payment_date: new Date().toISOString(),
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
    ],
  } satisfies IShoppingMallOrder.ICreate;
  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: orderCreateBody,
    });
  typia.assert(order);

  // 5. Seller creates a shipment tracking record for the order
  const shipmentTrackingCreateBody = {
    shopping_mall_order_id: order.id,
    tracking_number: "TRACK123456789",
    carrier_name: "CarrierX",
    shipping_status: "shipped",
    shipped_at: new Date().toISOString(),
    delivered_at: null,
    deleted_at: null,
  } satisfies IShoppingMallShipmentTracking.ICreate;
  const shipmentTracking: IShoppingMallShipmentTracking =
    await api.functional.shoppingMall.seller.shipmentTrackings.create(
      connection,
      {
        body: shipmentTrackingCreateBody,
      },
    );
  typia.assert(shipmentTracking);

  // 6. Seller updates the shipment tracking record
  const updatedNumber = "TRACK987654321";
  const updatedCarrier = "CarrierY";
  const updatedStatus = "in_transit";
  const updatedShippedAt = new Date().toISOString();
  const updatedDeliveredAt = null;
  const updateBody = {
    tracking_number: updatedNumber,
    carrier_name: updatedCarrier,
    shipping_status: updatedStatus,
    shipped_at: updatedShippedAt,
    delivered_at: updatedDeliveredAt,
  } satisfies IShoppingMallShipmentTracking.IUpdate;
  const updatedShipmentTracking: IShoppingMallShipmentTracking =
    await api.functional.shoppingMall.seller.shipmentTrackings.updateShipmentTracking(
      connection,
      {
        id: shipmentTracking.id,
        body: updateBody,
      },
    );
  typia.assert(updatedShipmentTracking);
  TestValidator.equals(
    "tracking number should be updated",
    updatedShipmentTracking.tracking_number,
    updatedNumber,
  );
  TestValidator.equals(
    "carrier name should be updated",
    updatedShipmentTracking.carrier_name,
    updatedCarrier,
  );
  TestValidator.equals(
    "shipping status should be updated",
    updatedShipmentTracking.shipping_status,
    updatedStatus,
  );
  TestValidator.equals(
    "shipped_at should be updated",
    updatedShipmentTracking.shipped_at,
    updatedShippedAt,
  );
  TestValidator.equals(
    "delivered_at should be updated",
    updatedShipmentTracking.delivered_at,
    updatedDeliveredAt,
  );

  // 7. Validate persistence of update by performing read-back
  // (simulate by calling updateShipmentTracking and expect same data)
  const readBackShipmentTracking =
    await api.functional.shoppingMall.seller.shipmentTrackings.updateShipmentTracking(
      connection,
      {
        id: shipmentTracking.id,
        body: updateBody,
      },
    );
  typia.assert(readBackShipmentTracking);
  TestValidator.equals(
    "read-back tracking number matches",
    readBackShipmentTracking.tracking_number,
    updatedNumber,
  );
  TestValidator.equals(
    "read-back carrier name matches",
    readBackShipmentTracking.carrier_name,
    updatedCarrier,
  );
  TestValidator.equals(
    "read-back shipping status matches",
    readBackShipmentTracking.shipping_status,
    updatedStatus,
  );
  TestValidator.equals(
    "read-back shipped_at matches",
    readBackShipmentTracking.shipped_at,
    updatedShippedAt,
  );
  TestValidator.equals(
    "read-back delivered_at matches",
    readBackShipmentTracking.delivered_at,
    updatedDeliveredAt,
  );

  // 8. Validate unauthorized access prevention
  // Customer tries updating shipment tracking - should fail
  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: "CustPass1234!",
      ip: null,
      href: "http://localhost/",
      referrer: "http://localhost/prev",
    } satisfies IShoppingMallCustomer.ILogin,
  });
  await TestValidator.error(
    "customer cannot update shipment tracking",
    async () => {
      await api.functional.shoppingMall.seller.shipmentTrackings.updateShipmentTracking(
        connection,
        {
          id: shipmentTracking.id,
          body: updateBody,
        },
      );
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import type { IShoppingMallAdmin } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallAdmin";
import type { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import type { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import type { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import type { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import type { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import type { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import type { IShoppingMallProduct } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProduct";
import type { IShoppingMallProductApproval } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductApproval";
import type { IShoppingMallProductCategory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductCategory";
import type { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import type { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import type { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import type { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import type { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import type { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import type { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import type { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";

/**
 * This E2E test function validates the shipment tracking record deletion flow
 * by an admin user. It ensures only authorized admins can delete shipment
 * tracking records linked to orders.
 *
 * The test covers multi-actor authentication (admin, seller, customer), product
 * registration, order creation, shipment tracking creation, and the deletion
 * itself. Permissions are validated by attempting unauthorized deletion.
 *
 * Validation is performed via typia type assertions and TestValidator for
 * business logic correctness, error handling, and data integrity after
 * deletion.
 *
 * Step-by-step:
 *
 * 1. Admin joins and logs in.
 * 2. Seller joins and logs in.
 * 3. Seller creates a product.
 * 4. Customer joins and logs in.
 * 5. Customer creates an order for the product.
 * 6. Admin creates shipment tracking linked to order.
 * 7. Admin deletes shipment tracking record.
 * 8. Verify response and shipment tracking removal.
 * 9. Verify that accessing or deleting deleted shipment tracking returns not found
 *    error.
 * 10. Attempt unauthorized deletion from customer and seller contexts and verify
 *     errors.
 */
export async function test_api_shipment_tracking_deletion_by_admin(
  connection: api.IConnection,
) {
  // 1. Admin joins and logs in
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const adminPassword = "ComplexP@ssword123";

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, {
      body: {
        email: adminEmail,
        password: adminPassword,
        full_name: RandomGenerator.name(2),
      } satisfies IShoppingMallAdmin.IJoin,
    });
  typia.assert(admin);

  await api.functional.auth.admin.login(connection, {
    body: {
      email: adminEmail,
      password: adminPassword,
      ip: null,
      href: "http://localhost/admin/login",
      referrer: "http://localhost/",
    } satisfies IShoppingMallAdmin.ILogin,
  });

  // 2. Seller joins and logs in
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = "ComplexP@ssword123";

  const seller: IShoppingMallSeller.IAuthorized =
    await api.functional.auth.seller.join(connection, {
      body: {
        email: sellerEmail,
        password: sellerPassword,
        store_name: RandomGenerator.name(3),
      } satisfies IShoppingMallSeller.ICreate,
    });
  typia.assert(seller);

  await api.functional.auth.seller.login(connection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      ip: null,
      href: "http://localhost/seller/login",
      referrer: "http://localhost/",
    } satisfies IShoppingMallSeller.ILogin,
  });

  // 3. Seller creates a product
  const product: IShoppingMallProduct =
    await api.functional.shoppingMall.seller.products.create(connection, {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.name(3),
        description: RandomGenerator.paragraph({
          sentences: 4,
          wordMin: 4,
          wordMax: 7,
        }),
        brand: RandomGenerator.name(1),
      } satisfies IShoppingMallProduct.ICreate,
    });
  typia.assert(product);

  // 4. Customer joins and logs in
  const customerEmail = typia.random<string & tags.Format<"email">>();
  const customerPassword = "ComplexP@ssword123";

  const customer: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.join(connection, {
      body: {
        email: customerEmail,
        password: customerPassword,
        nickname: RandomGenerator.name(2),
      } satisfies IShoppingMallCustomer.ICreate,
    });
  typia.assert(customer);

  await api.functional.auth.customer.login(connection, {
    body: {
      email: customerEmail,
      password: customerPassword,
      ip: null,
      href: "http://localhost/customer/login",
      referrer: "http://localhost/",
    } satisfies IShoppingMallCustomer.ILogin,
  });

  // 5. Customer creates an order for the product
  const orderItem: IShoppingMallOrderItem.ICreate = {
    shopping_mall_product_sku_id: product.shopping_mall_product_skus?.length
      ? product.shopping_mall_product_skus[0].id
      : typia.random<string & tags.Format<"uuid">>(),
    quantity: 1,
    unit_price: 10000,
    total_price: 10000,
  };

  const order: IShoppingMallOrder =
    await api.functional.shoppingMall.customer.orders.create(connection, {
      body: {
        order_code: RandomGenerator.alphaNumeric(10),
        shipping_address: `${RandomGenerator.name(1)} street, City, Country`,
        shopping_mall_order_items: [orderItem],
      } satisfies IShoppingMallOrder.ICreate,
    });
  typia.assert(order);

  // 6. Admin creates shipment tracking linked to order
  const shipmentTracking: IShoppingMallShipmentTracking =
    await api.functional.shoppingMall.admin.shipmentTrackings.create(
      connection,
      {
        body: {
          shopping_mall_order_id: order.id,
          tracking_number: RandomGenerator.alphaNumeric(15).toUpperCase(),
          carrier_name: RandomGenerator.name(1),
          shipping_status: "shipped",
          shipped_at: new Date().toISOString(),
          delivered_at: null,
          deleted_at: null,
        } satisfies IShoppingMallShipmentTracking.ICreate,
      },
    );
  typia.assert(shipmentTracking);

  // 7. Admin deletes shipment tracking record
  const deleteResponse =
    await api.functional.shoppingMall.admin.shipmentTrackings.eraseShipmentTracking(
      connection,
      {
        id: shipmentTracking.id,
      },
    );
  TestValidator.equals(
    "shipment tracking deletion response is void",
    deleteResponse,
    undefined,
  );

  // 8. Attempt to delete the same shipment tracking again (expect not found error)
  await TestValidator.error(
    "deleting already deleted shipment tracking throws error",
    async () => {
      await api.functional.shoppingMall.admin.shipmentTrackings.eraseShipmentTracking(
        connection,
        {
          id: shipmentTracking.id,
        },
      );
    },
  );

  // 9. Unauthorized deletion attempts from customer
  await api.functional.auth.customer.login(connection, {
    body: {
