    connection,
    {
      body: {
        email: customerEmail,
        password: "password123",
        href: "https://test.page.com/login",
        referrer: "https://test.page.com",
      } satisfies IShoppingMallCustomer.ILogin,
    },
  );
  typia.assert(customerAuthorized);

  // 3. Seller registers with join
