/**
 * Validates the retrieval of a shopping cart by its unique UUID id by the
 * authenticated owning customer.
 *
 * The test follows a full workflow: customer registration and login, admin
 * registration and login for role assignment, assigning the "customer" role
 * through the admin API, creation of a shopping cart tied to the customer and
 * session, and finally retrieving the cart by its id.
 *
 * The test ensures all entities follow proper authentication flows switching
 * contexts appropriately between actors.
 *
 * Validations check the correctness of ownership identifiers, session
 * consistency, cart items structure, and customer session information.
 *
 * This provides end-to-end confidence that shopping cart retrieval is
 * accurately restricted and data integrity is maintained.
 *
 * Steps:
 *
 * 1. Register customer user (actor 1) with a valid email and nickname.
 * 2. Login customer user.
 * 3. Register admin user (actor 2) with a valid email and full name.
 * 4. Login admin user.
 * 5. Assign "customer" role to the registered customer.
 * 6. Switch authentication context back to the customer.
 * 7. Create a new shopping cart associated with the customer and session.
 * 8. Retrieve the cart by its id and validate complete data integrity.
 */
export async function test_api_shopping_cart_retrieval_by_customer(
  connection: api.IConnection,
) {
  // 1. Register customer user (actor 1)
  const customerCreateBody = {
    email: `${RandomGenerator.name(1).toLowerCase().replace(/\s+/g, "")}@example.com`,
    password: "12345678",
