  // 2. Login customer user (actor 1)
  const customerLoginBody = {
    email: customerCreateBody.email,
    password: customerCreateBody.password,
    href: "https://example.com/login",
    referrer: "https://example.com",
  } satisfies IShoppingMallCustomer.ILogin;

  const customerLogin: IShoppingMallCustomer.IAuthorized =
    await api.functional.auth.customer.login(connection, {
      body: customerLoginBody,
    });
  typia.assert(customerLogin);

  // 3. Register admin user (actor 2)
  const adminCreateBody = {
    email: `${RandomGenerator.name(1).toLowerCase().replace(/\s+/g, "")}@example.com`,
    password: "adminpassword",
    full_name: RandomGenerator.name(),
  } satisfies IShoppingMallAdmin.IJoin;

  const admin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.join(connection, { body: adminCreateBody });
  typia.assert(admin);

  // 4. Login admin user (actor 2)
  const adminLoginBody = {
    email: adminCreateBody.email,
    password: adminCreateBody.password,
    href: "https://admin.example.com/login",
    referrer: "https://admin.example.com",
  } satisfies IShoppingMallAdmin.ILogin;

  const adminLogin: IShoppingMallAdmin.IAuthorized =
    await api.functional.auth.admin.login(connection, { body: adminLoginBody });
  typia.assert(adminLogin);

  // 5. Assign customer role to customer user
  const userRoleCreateBody = {
    user_id: customer.id,
    role_name: "customer",
  } satisfies IShoppingMallUserRole.ICreate;

  const userRole: IShoppingMallUserRole =
    await api.functional.shoppingMall.admin.userRoles.create(connection, {
      body: userRoleCreateBody,
    });
  typia.assert(userRole);

  // 6. Switch back to customer user login (actor 1)
  await api.functional.auth.customer.login(connection, {
    body: customerLoginBody,
  });

  // 7. Create shopping cart for customer user
  const shoppingCartCreateBody = {
    shopping_mall_customer_id: customer.id,
    shopping_mall_customer_session_id: typia.random<
      string & tags.Format<"uuid">
    >() satisfies string as string,
  } satisfies IShoppingMallShoppingCart.ICreate;

  const shoppingCart: IShoppingMallShoppingCart =
    await api.functional.shoppingMall.customer.shoppingCarts.create(
      connection,
      { body: shoppingCartCreateBody },
    );
  typia.assert(shoppingCart);

  // 8. Retrieve shopping cart by id
  const retrievedCart: IShoppingMallShoppingCart =
    await api.functional.shoppingMall.customer.shoppingCarts.at(connection, {
      id: shoppingCart.id,
    });
  typia.assert(retrievedCart);

  // Validate ownership and session match
  TestValidator.equals(
    "shopping cart customer id matches",
    retrievedCart.shopping_mall_customer_id,
    customer.id,
  );
  TestValidator.equals(
    "shopping cart session id match",
    retrievedCart.shopping_mall_customer_session_id,
    shoppingCartCreateBody.shopping_mall_customer_session_id,
  );

  // Validate shopping mall cart items structure if exist
  if (retrievedCart.shopping_mall_cart_items) {
    for (const item of retrievedCart.shopping_mall_cart_items) {
      typia.assert(item);
      TestValidator.predicate("cart item quantity > 0", item.quantity > 0);
      TestValidator.predicate(
        "cart item sku id defined",
        typeof item.shopping_mall_product_sku_id === "string",
      );
    }
  }

  // Validate customer session and customer info if present
  if (retrievedCart.customerSession) {
    typia.assert(retrievedCart.customerSession);
    TestValidator.equals(
      "customer session customer id matches",
      retrievedCart.customerSession.shopping_mall_customer_id,
      customer.id,
    );
  }
  if (retrievedCart.customer) {
    typia.assert(retrievedCart.customer);
    TestValidator.equals(
      "retrieved customer id matches",
      retrievedCart.customer.id,
      customer.id,
    );
  }
}

