  await TestValidator.error(
    "deleting non-existent cart item should fail",
    async () => {
      await api.functional.shoppingMall.customer.shoppingCarts.items.eraseCartItem(
        connection,
        {
          cartId: shoppingCart.id,
          itemId: cartItem.id,
        },
      );
    },
  );
