import { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerWishlists(props: {
  customer: CustomerPayload;
  body: IShoppingMallWishlist.IRequest;
}): Promise<IPageIShoppingMallWishlist.ISummary> {
  const { customer, body } = props;

  const page = body.page;
  const limit = body.limit;
  const skip = (page - 1) * limit;

  const createdAtFilter: {
    gte?: string & tags.Format<"date-time">;
    lte?: string & tags.Format<"date-time">;
  } = {};
  if (body.created_at_from !== undefined && body.created_at_from !== null) {
    createdAtFilter.gte = body.created_at_from;
  }
  if (body.created_at_to !== undefined && body.created_at_to !== null) {
    createdAtFilter.lte = body.created_at_to;
  }

  const updatedAtFilter: {
    gte?: string & tags.Format<"date-time">;
    lte?: string & tags.Format<"date-time">;
  } = {};
  if (body.updated_at_from !== undefined && body.updated_at_from !== null) {
    updatedAtFilter.gte = body.updated_at_from;
  }
  if (body.updated_at_to !== undefined && body.updated_at_to !== null) {
    updatedAtFilter.lte = body.updated_at_to;
  }

  const where = {
    shopping_mall_customer_id: customer.id,
    ...(body.shopping_mall_customer_session_id !== undefined &&
      body.shopping_mall_customer_session_id !== null && {
        shopping_mall_customer_session_id:
          body.shopping_mall_customer_session_id,
      }),
    ...(Object.keys(createdAtFilter).length > 0 && {
      created_at: createdAtFilter,
    }),
    ...(Object.keys(updatedAtFilter).length > 0 && {
      updated_at: updatedAtFilter,
    }),
    ...(body.include_deleted === true ? {} : { deleted_at: null }),
  };

  const [wishlists, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_wishlists.findMany({
      where,
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
      include: { shopping_mall_wishlist_items: true },
    }),
    MyGlobal.prisma.shopping_mall_wishlists.count({ where }),
  ]);

  return {
    pagination: {
      current: page satisfies number as number,
      limit: limit satisfies number as number,
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: wishlists.map((wishlist) => ({
      id: wishlist.id,
      shopping_mall_customer_id: wishlist.shopping_mall_customer_id,
      shopping_mall_customer_session_id:
        wishlist.shopping_mall_customer_session_id,
      created_at: toISOStringSafe(wishlist.created_at),
      updated_at: toISOStringSafe(wishlist.updated_at),
      deleted_at: wishlist.deleted_at
        ? toISOStringSafe(wishlist.deleted_at)
        : null,
      shopping_mall_wishlist_items: wishlist.shopping_mall_wishlist_items.map(
        (item) => ({
          id: item.id,
          shopping_mall_wishlist_id: item.shopping_mall_wishlist_id,
          shopping_mall_product_sku_id: item.shopping_mall_product_sku_id,
          quantity: item.quantity,
          created_at: toISOStringSafe(item.created_at),
          updated_at: toISOStringSafe(item.updated_at),
          deleted_at: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
        }),
      ),
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallWishlistItem";
import { IPageIShoppingMallWishlistItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallWishlistItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function patchShoppingMallCustomerWishlistsWishlistIdItems(props: {
  customer: CustomerPayload;
  wishlistId: string & tags.Format<"uuid">;
  body: IShoppingMallWishlistItem.IRequest;
}): Promise<IPageIShoppingMallWishlistItem.ISummary> {
  const { customer, wishlistId, body } = props;

  const wishlist = await MyGlobal.prisma.shopping_mall_wishlists.findUnique({
    where: { id: wishlistId },
    select: { shopping_mall_customer_id: true, deleted_at: true },
  });

  if (!wishlist || wishlist.deleted_at !== null) {
    throw new HttpException("Wishlist not found", 404);
  }

  if (wishlist.shopping_mall_customer_id !== customer.id) {
    throw new HttpException("Forbidden: Not the owner of the wishlist", 403);
  }

  if (body.delete_item_ids && body.delete_item_ids.length > 0) {
    await Promise.all(
      body.delete_item_ids.map(async (itemId) => {
        const deleted =
          await MyGlobal.prisma.shopping_mall_wishlist_items.deleteMany({
            where: {
              id: itemId,
              shopping_mall_wishlist_id: wishlistId,
            },
          });
      }),
    );
  }

  if (body.update_items && body.update_items.length > 0) {
    await Promise.all(
      body.update_items.map(async (updateItem) => {
        if (updateItem.id) {
          const existing =
            await MyGlobal.prisma.shopping_mall_wishlist_items.findFirst({
              where: {
                id: updateItem.id,
                shopping_mall_wishlist_id: wishlistId,
              },
              select: { id: true },
            });
          if (existing) {
            await MyGlobal.prisma.shopping_mall_wishlist_items.update({
              where: { id: updateItem.id },
              data: {
                shopping_mall_product_sku_id:
                  updateItem.shopping_mall_product_sku_id,
                quantity: updateItem.quantity,
                updated_at: toISOStringSafe(new Date()),
                deleted_at:
                  updateItem.deleted_at === null
                    ? null
                    : (updateItem.deleted_at ?? undefined),
              },
            });
          }
        }
      }),
    );
  }

  const whereCondition = {
    shopping_mall_wishlist_id: wishlistId,
    deleted_at: null,
    ...(body.filter_shopping_mall_customer_session_id !== undefined &&
      body.filter_shopping_mall_customer_session_id !== null && {
        shopping_mall_customer_session_id:
          body.filter_shopping_mall_customer_session_id,
      }),
    ...(body.filter_shopping_mall_product_sku_id !== undefined &&
      body.filter_shopping_mall_product_sku_id !== null && {
        shopping_mall_product_sku_id: body.filter_shopping_mall_product_sku_id,
      }),
    ...(body.filter_shopping_mall_product_sku_ids !== undefined &&
      body.filter_shopping_mall_product_sku_ids !== null && {
        shopping_mall_product_sku_id: {
          in: body.filter_shopping_mall_product_sku_ids,
        },
      }),
  };

  const orderBy =
    body.sort_field === "quantity"
      ? {
          quantity: (body.sort_order === "asc" ? "asc" : "desc") satisfies
            | "asc"
            | "desc" as "asc" | "desc",
        }
      : {
          created_at: (body.sort_order === "asc" ? "asc" : "desc") satisfies
            | "asc"
            | "desc" as "asc" | "desc",
        };

  const page: number & tags.Type<"int32"> & tags.Minimum<0> = (body.page ??
    1) satisfies number as number;
  const limit: number & tags.Type<"int32"> & tags.Minimum<0> = (body.limit ??
    10) satisfies number as number;

  const skip = (page - 1) * limit;

  const [results, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_wishlist_items.findMany({
      where: whereCondition,
      orderBy,
      skip,
      take: limit,
    }),
    MyGlobal.prisma.shopping_mall_wishlist_items.count({
      where: whereCondition,
    }),
  ]);

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: results.map((item) => ({
      id: item.id,
      shopping_mall_wishlist_id: item.shopping_mall_wishlist_id,
      shopping_mall_product_sku_id: item.shopping_mall_product_sku_id,
      quantity: item.quantity,
      created_at: toISOStringSafe(item.created_at),
      updated_at: toISOStringSafe(item.updated_at),
      deleted_at: item.deleted_at ? toISOStringSafe(item.deleted_at) : null,
    })),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postAuthCustomerRefresh(props: {
  customer: CustomerPayload;
  body: IShoppingMallCustomer.IRefresh;
}): Promise<IShoppingMallCustomer.IAuthorized> {
  let decoded = jwt.verify(
    props.body.refresh_token,
    MyGlobal.env.JWT_SECRET_KEY,
    { issuer: "autobe" },
  );

  if (typeof decoded === "string") {
    throw new HttpException("Invalid token payload", 403);
  }

  if (
    decoded.type !== "customer" ||
    decoded.id !== props.customer.id ||
    decoded.session_id !== props.customer.session_id
  ) {
    throw new HttpException("Invalid token payload", 403);
  }

  const session =
    await MyGlobal.prisma.shopping_mall_customer_sessions.findFirst({
      where: {
        id: decoded.session_id,
        shopping_mall_customer_id: decoded.id,
      },
      include: {
        shoppingMallCustomer: true,
      },
    });

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }

  if (session.shoppingMallCustomer.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  const now_iso = new Date().toISOString();
  const accessExpires = new Date(Date.now() + 60 * 60 * 1000);
  const refreshExpires = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000);

  const token = {
    access: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        created_at: now_iso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "1h", issuer: "autobe" },
    ),
    refresh: jwt.sign(
      {
        type: decoded.type,
        id: decoded.id,
        session_id: decoded.session_id,
        tokenType: "refresh",
        created_at: now_iso,
      },
      MyGlobal.env.JWT_SECRET_KEY,
      { expiresIn: "7d", issuer: "autobe" },
    ),
    expired_at: toISOStringSafe(accessExpires),
    refreshable_until: toISOStringSafe(refreshExpires),
  };

  await MyGlobal.prisma.shopping_mall_customer_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: toISOStringSafe(refreshExpires) },
  });

  const customer = session.shoppingMallCustomer;

  return {
    id: customer.id,
    email: customer.email,
    nickname: customer.nickname,
    created_at: toISOStringSafe(customer.created_at),
    updated_at: toISOStringSafe(customer.updated_at),
    deleted_at:
      customer.deleted_at !== null
        ? toISOStringSafe(customer.deleted_at)
        : null,
    token: token,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSeller } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSeller";
import { IShoppingMallSellerSession } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerSession";
import { IShoppingMallSellerProfile } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSellerProfile";
import { IAuthorizationToken } from "@ORGANIZATION/PROJECT-api/lib/structures/IAuthorizationToken";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function postAuthSellerRefresh(props: {
  seller: SellerPayload;
  body: IShoppingMallSeller.IRefresh;
}): Promise<IShoppingMallSeller.IAuthorized> {
  // Step 1: Verify and decode the refresh token
  let decodedRaw = jwt.verify(
    props.body.refreshToken,
    MyGlobal.env.JWT_SECRET_KEY,
    {
      issuer: "autobe",
    },
  );

  // Narrow decodedRaw to JwtPayload
  if (typeof decodedRaw !== "object" || decodedRaw === null) {
    throw new HttpException("Invalid or expired refresh token", 401);
  }

  const decoded = decodedRaw as {
    type: string;
    id: string & tags.Format<"uuid">;
    session_id: string & tags.Format<"uuid">;
  };

  // Step 2: Validate token type
  if (decoded.type !== "seller") {
    throw new HttpException("Invalid token type", 403);
  }

  // Step 3: Validate session and seller
  const session = await MyGlobal.prisma.shopping_mall_seller_sessions.findFirst(
    {
      where: {
        id: decoded.session_id,
        shopping_mall_seller_id: decoded.id,
      },
      include: {
        shoppingMallSeller: true,
      },
    },
  );

  if (!session) {
    throw new HttpException("Session expired or revoked", 401);
  }
  if (session.shoppingMallSeller.deleted_at !== null) {
    throw new HttpException("Account has been deleted", 403);
  }

  // Step 4: Generate new access and refresh tokens
  const now = toISOStringSafe(new Date());
  const accessExpires = toISOStringSafe(new Date(Date.now() + 60 * 60 * 1000));
  const refreshExpires = toISOStringSafe(
    new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
  );

  const access = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "1h", issuer: "autobe" },
  );

  const refresh = jwt.sign(
    {
      type: decoded.type,
      id: decoded.id,
      session_id: decoded.session_id,
      tokenType: "refresh",
      created_at: now,
    },
    MyGlobal.env.JWT_SECRET_KEY,
    { expiresIn: "7d", issuer: "autobe" },
  );

  // Step 5: Update session expiration
  await MyGlobal.prisma.shopping_mall_seller_sessions.update({
    where: { id: decoded.session_id },
    data: { expired_at: refreshExpires },
  });

  // Step 6: Compose returned authorized seller object
  const seller = session.shoppingMallSeller;

  return {
    id: seller.id,
    email: seller.email,
    password_hash: seller.password_hash,
    store_name: seller.store_name,
    created_at: toISOStringSafe(seller.created_at),
    updated_at: toISOStringSafe(seller.updated_at),
    deleted_at:
      seller.deleted_at === null
        ? undefined
        : toISOStringSafe(seller.deleted_at),
    shopping_mall_seller_sessions: undefined,
    shopping_mall_seller_profiles: undefined,
    token: {
      access,
      refresh,
      expired_at: accessExpires,
      refreshable_until: refreshExpires,
    },
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
