export async function putShoppingMallSellerSkuInventoriesId(props: {
  seller: SellerPayload;
  id: string & tags.Format<"uuid">;
  body: IShoppingMallSkuInventory.IUpdate;
}): Promise<IShoppingMallSkuInventory> {
  const { seller, id, body } = props;

  const existing =
    await MyGlobal.prisma.shopping_mall_sku_inventories.findUnique({
      where: { id },
    });

  if (!existing) {
    throw new HttpException("SKU inventory record not found", 404);
  }

  if (body.quantity < 0) {
    throw new HttpException("Quantity must be non-negative", 400);
  }

  if (
    !["in stock", "out of stock", "backordered"].includes(body.stock_status)
  ) {
