}): Promise<IShoppingMallSeller.IAuthorized> {
  // Check existing seller by email
  const existingSeller = await MyGlobal.prisma.shopping_mall_sellers.findFirst({
    where: {
      email: props.body.email,
      deleted_at: null,
    },
  });

  if (existingSeller !== null) {
