export async function getShoppingMallSellerOrdersOrderCodeItemsItemId(props: {
  seller: SellerPayload;
  orderCode: string;
  itemId: string & tags.Format<"uuid">;
}): Promise<IShoppingMallOrderItem> {
  const { seller, orderCode, itemId } = props;

  const order = await MyGlobal.prisma.shopping_mall_orders.findFirst({
    where: {
      order_code: orderCode,
      deleted_at: null,
    },
    select: { id: true },
  });

  if (!order) throw new HttpException("Order not found", 404);

  const orderItem = await MyGlobal.prisma.shopping_mall_order_items.findFirst({
    where: {
      id: itemId,
      shopping_mall_order_id: order.id,
      deleted_at: null,
    },
  });

  if (!orderItem) throw new HttpException("Order item not found", 404);

  const sku = await MyGlobal.prisma.shopping_mall_product_skus.findFirst({
    where: {
      id: orderItem.shopping_mall_product_sku_id,
      deleted_at: null,
    },
  });

  if (!sku)
    throw new HttpException("Unauthorized: seller does not own the SKU", 403);

  return {
    id: orderItem.id,
    shopping_mall_order_id: orderItem.shopping_mall_order_id,
    shopping_mall_product_sku_id: orderItem.shopping_mall_product_sku_id,
    quantity: orderItem.quantity,
    unit_price: orderItem.unit_price,
    total_price: orderItem.total_price,
    created_at: toISOStringSafe(orderItem.created_at),
    updated_at: toISOStringSafe(orderItem.updated_at),
    deleted_at: orderItem.deleted_at
      ? toISOStringSafe(orderItem.deleted_at)
      : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IPageIShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallOrderItem";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerOrdersOrderCodeItems(props: {
  seller: SellerPayload;
  orderCode: string;
  body: IShoppingMallOrderItem.IRequest;
}): Promise<IPageIShoppingMallOrderItem.ISummary> {
  const { seller, orderCode, body } = props;
  const page = body.page ?? 1;
  const limit = body.limit ?? 20;
  const skip = (page - 1) * limit;

  const order = await MyGlobal.prisma.shopping_mall_orders.findUnique({
    where: { order_code: orderCode },
    select: { id: true },
  });

  if (!order) {
    throw new HttpException(`Order with code ${orderCode} not found`, 404);
  }

  const where: any = {
    shopping_mall_order_id: order.id,
  };

  if (body.search !== undefined && body.search !== null) {
    where.OR = [
      { sku_code: { contains: body.search } },
      { attributes_json: { contains: body.search } },
    ];
  }

  const validSortFields = [
    "quantity",
    "unit_price",
    "total_price",
    "created_at",
    "updated_at",
  ];

  const orderBy: Record<string, "asc" | "desc"> =
    body.sort_by && validSortFields.includes(body.sort_by)
      ? { [body.sort_by]: body.order === "asc" ? "asc" : "desc" }
      : { created_at: "desc" };

  const [total, results] = await Promise.all([
    MyGlobal.prisma.shopping_mall_order_items.count({
      where: where,
    }),
    MyGlobal.prisma.shopping_mall_order_items.findMany({
      where: where,
      take: limit,
      skip: skip,
      orderBy: orderBy,
    }),
  ]);

  const productSkuIds = results.map(
    (item) => item.shopping_mall_product_sku_id,
  );

  const productSkusArray =
    await MyGlobal.prisma.shopping_mall_product_skus.findMany({
      where: { id: { in: productSkuIds } },
      select: {
        id: true,
        sku_code: true,
        price: true,
        attributes_json: true,
      },
    });

  const productSkusMap = new Map(productSkusArray.map((sku) => [sku.id, sku]));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data: results.map((item) => {
      const sku = productSkusMap.get(item.shopping_mall_product_sku_id);
      if (!sku) {
        throw new HttpException(
          `Product SKU not found for id ${item.shopping_mall_product_sku_id}`,
          404,
        );
      }
      return {
        id: item.id,
        quantity: item.quantity,
        unit_price: item.unit_price,
        total_price: item.total_price,
        product_sku: {
          id: sku.id satisfies string & tags.Format<"uuid"> as string &
            tags.Format<"uuid">,
          sku_code: sku.sku_code,
          price: sku.price,
          attributes_json: sku.attributes_json ?? null,
        },
      };
    }),
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallSkuInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallSkuInventory";
import { IPageIShoppingMallSkuInventory } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIShoppingMallSkuInventory";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IShoppingMallProductSku } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductSku";
import { IShoppingMallStockAdjustment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallStockAdjustment";
import { IShoppingMallLowStockAlert } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallLowStockAlert";
import { SellerPayload } from "../decorators/payload/SellerPayload";

export async function patchShoppingMallSellerSkuInventories(props: {
  seller: SellerPayload;
  body: IShoppingMallSkuInventory.IRequest;
}): Promise<IPageIShoppingMallSkuInventory.ISummary> {
  const { body } = props;

  const page = (body.page ?? 1) as number &
    tags.Type<"int32"> &
    tags.Minimum<0> as number;
  const limit = (body.limit ?? 10) as number &
    tags.Type<"int32"> &
    tags.Minimum<0> as number;
  const skip = (page - 1) * limit;

  const where: Prisma.shopping_mall_sku_inventoriesWhereInput = {
    deleted_at: null,
    ...(body.shopping_mall_product_sku_code !== undefined &&
      body.shopping_mall_product_sku_code !== null && {
        productSku: {
          sku_code: {
            contains: body.shopping_mall_product_sku_code,
          },
        },
      }),
    ...(body.stock_status !== undefined &&
      body.stock_status !== null && {
        stock_status: {
          contains: body.stock_status,
        },
      }),
    ...(body.min_quantity !== undefined &&
      body.min_quantity !== null && {
        quantity: {
          gte: body.min_quantity,
        },
      }),
    ...(body.max_quantity !== undefined &&
      body.max_quantity !== null && {
        quantity: {
          lte: body.max_quantity,
        },
      }),
    ...(body.date_from !== undefined &&
      body.date_from !== null && {
        updated_at: {
          gte: body.date_from,
        },
      }),
    ...(body.date_to !== undefined &&
      body.date_to !== null && {
        updated_at: {
          lte: body.date_to,
        },
      }),
  };

  const orderBy: Prisma.shopping_mall_sku_inventoriesOrderByWithRelationInput =
    body.sort_by !== null && body.sort_by !== undefined
      ? {
          [body.sort_by]: (body.order !== null &&
          body.order !== undefined &&
          (body.order === "asc" || body.order === "desc")
            ? body.order
            : "asc") satisfies Prisma.SortOrder,
        }
      : ({
          created_at: "desc",
        } satisfies Prisma.shopping_mall_sku_inventoriesOrderByWithRelationInput);

  const [results, total] = await Promise.all([
    MyGlobal.prisma.shopping_mall_sku_inventories.findMany({
      where,
      include: {
        productSku: true,
      },
      skip,
      take: limit,
      orderBy,
    }),
    MyGlobal.prisma.shopping_mall_sku_inventories.count({ where }),
  ]);

  type ResultType = (typeof results)[number] & {
    productSku: {
      id: string & tags.Format<"uuid">;
      sku_code: string;
      price: number & tags.Type<"double"> & tags.Minimum<0>;
      attributes_json: string | null;
      created_at: string & tags.Format<"date-time">;
      updated_at: string & tags.Format<"date-time">;
    };
    shopping_mall_stock_adjustments: {
      id: string & tags.Format<"uuid">;
      shopping_mall_product_sku_id: string & tags.Format<"uuid">;
      adjustment_type: string;
      quantity: number & tags.Type<"int32"> & tags.Minimum<0>;
      actor_type: string;
      actor_id: string & tags.Format<"uuid">;
      created_at: string & tags.Format<"date-time">;
      productSku: {
        id: string & tags.Format<"uuid">;
        sku_code: string;
        price: number & tags.Type<"double"> & tags.Minimum<0>;
        attributes_json: string | null;
        created_at: string & tags.Format<"date-time">;
        updated_at: string & tags.Format<"date-time">;
      };
    }[];
    shopping_mall_low_stock_alerts: {
      id: string & tags.Format<"uuid">;
      shopping_mall_product_sku_id: string & tags.Format<"uuid">;
      alerted_at: string & tags.Format<"date-time">;
      resolved: boolean;
      resolved_at: (string & tags.Format<"date-time">) | null;
    }[];
  };

  const typedResults = results as ResultType[];

  const data = typedResults.map((record) => ({
    id: record.id,
    shopping_mall_product_sku_id: record.shopping_mall_product_sku_id,
    quantity: record.quantity,
    stock_status: record.stock_status,
    created_at: toISOStringSafe(record.created_at),
    updated_at: toISOStringSafe(record.updated_at),
    deleted_at: record.deleted_at
      ? toISOStringSafe(record.deleted_at)
      : undefined,
    productSku: {
      id: record.productSku.id,
      sku_code: record.productSku.sku_code,
      price: record.productSku.price,
      attributes_json: record.productSku.attributes_json ?? null,
      created_at: toISOStringSafe(record.productSku.created_at),
      updated_at: toISOStringSafe(record.productSku.updated_at),
    },
    stockAdjustmentsCount: record.shopping_mall_stock_adjustments.length,
    lowStockAlertsCount: record.shopping_mall_low_stock_alerts.length,
    latestStockAdjustment:
      record.shopping_mall_stock_adjustments.length > 0
        ? {
            id: record.shopping_mall_stock_adjustments[0].id,
            shopping_mall_product_sku_id:
              record.shopping_mall_stock_adjustments[0]
                .shopping_mall_product_sku_id,
            adjustment_type:
              record.shopping_mall_stock_adjustments[0].adjustment_type,
            quantity: record.shopping_mall_stock_adjustments[0].quantity,
            actor_type: record.shopping_mall_stock_adjustments[0].actor_type,
            actor_id: record.shopping_mall_stock_adjustments[0].actor_id,
            created_at: toISOStringSafe(
              record.shopping_mall_stock_adjustments[0].created_at,
            ),
            productSku: {
              id: record.shopping_mall_stock_adjustments[0].productSku.id,
              sku_code:
                record.shopping_mall_stock_adjustments[0].productSku.sku_code,
              price: record.shopping_mall_stock_adjustments[0].productSku.price,
              attributes_json:
                record.shopping_mall_stock_adjustments[0].productSku
                  .attributes_json ?? null,
              created_at: toISOStringSafe(
                record.shopping_mall_stock_adjustments[0].productSku.created_at,
              ),
              updated_at: toISOStringSafe(
                record.shopping_mall_stock_adjustments[0].productSku.updated_at,
              ),
            },
          }
        : undefined,
    latestLowStockAlert:
      record.shopping_mall_low_stock_alerts.length > 0
        ? {
            id: record.shopping_mall_low_stock_alerts[0].id,
            shopping_mall_product_sku_id:
              record.shopping_mall_low_stock_alerts[0]
                .shopping_mall_product_sku_id,
            alerted_at: toISOStringSafe(
              record.shopping_mall_low_stock_alerts[0].alerted_at,
            ),
            resolved: record.shopping_mall_low_stock_alerts[0].resolved,
            resolved_at: record.shopping_mall_low_stock_alerts[0].resolved_at
              ? toISOStringSafe(
                  record.shopping_mall_low_stock_alerts[0].resolved_at,
                )
              : null,
          }
        : undefined,
  }));

  return {
    pagination: {
      current: Number(page),
      limit: Number(limit),
      records: total,
      pages: Math.ceil(total / limit),
    },
    data,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallOrder } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrder";
import { IShoppingMallOrderItem } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderItem";
import { IShoppingMallPayment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallPayment";
import { IShoppingMallCustomer } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallCustomer";
import { IShoppingMallShipmentTracking } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallShipmentTracking";
import { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import { IShoppingMallOrderHistory } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderHistory";
import { IShoppingMallOrderCancellation } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallOrderCancellation";
import { IShoppingMallRefundRequest } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallRefundRequest";
import { IShoppingMallReturnShipment } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallReturnShipment";
import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function postShoppingMallCustomerOrders(props: {
  customer: CustomerPayload;
  body: IShoppingMallOrder.ICreate;
}): Promise<IShoppingMallOrder> {
  const { customer, body } = props;

  const skuIds = body.shopping_mall_order_items.map(
    (item) => item.shopping_mall_product_sku_id,
  );
  const skus = await MyGlobal.prisma.shopping_mall_product_skus.findMany({
    where: { id: { in: skuIds } },
  });

  if (skus.length !== skuIds.length) {
    throw new HttpException("One or more product SKUs are invalid", 400);
  }

  const totalAmount = body.shopping_mall_order_items.reduce(
    (sum, item) => sum + item.total_price,
    0,
  );

  const now = toISOStringSafe(new Date());

  const createdOrder = await MyGlobal.prisma.$transaction(async (tx) => {
    const order = await tx.shopping_mall_orders.create({
      data: {
        id: v4(),
        shopping_mall_customer_id: customer.id,
        order_code: body.order_code,
        shipping_address: body.shipping_address,
        status: "pending",
        payment_status: "unpaid",
        total_amount: totalAmount,
        created_at: now,
        updated_at: now,
        deleted_at: null,
        shopping_mall_order_items: {
          create: body.shopping_mall_order_items.map((item) => ({
            id: v4(),
            shopping_mall_product_sku_id: item.shopping_mall_product_sku_id,
            quantity: item.quantity,
            unit_price: item.unit_price,
            total_price: item.total_price,
            created_at: item.created_at ?? now,
            updated_at: item.updated_at ?? now,
            deleted_at: null,
          })),
        },
        shopping_mall_payments: body.shopping_mall_payments
          ? {
              create: body.shopping_mall_payments.map((payment) => ({
                id: v4(),
                payment_method: payment.payment_method,
                payment_status: payment.payment_status,
                payment_amount: payment.payment_amount,
                payment_date: payment.payment_date,
                created_at: payment.created_at,
                updated_at: payment.updated_at,
                deleted_at: null,
              })),
            }
          : undefined,
      },
      include: {
        shopping_mall_order_items: true,
        shopping_mall_payments: true,
        customer: true,
      },
    });

    return order;
  });

  return {
    id: createdOrder.id,
    shopping_mall_customer_id: createdOrder.shopping_mall_customer_id,
    order_code: createdOrder.order_code,
    shipping_address: createdOrder.shipping_address,
    status: createdOrder.status,
    payment_status: createdOrder.payment_status,
    total_amount: createdOrder.total_amount,
    created_at: toISOStringSafe(createdOrder.created_at),
    updated_at: toISOStringSafe(createdOrder.updated_at),
    deleted_at: createdOrder.deleted_at
      ? toISOStringSafe(createdOrder.deleted_at)
      : undefined,
    customer: {
      id: createdOrder.customer.id,
      email: createdOrder.customer.email,
      nickname: createdOrder.customer.nickname,
      created_at: toISOStringSafe(createdOrder.customer.created_at),
    },
    shopping_mall_order_items: createdOrder.shopping_mall_order_items.map(
      (item) => ({
        id: item.id,
        shopping_mall_order_id: createdOrder.id,
        shopping_mall_product_sku_id: item.shopping_mall_product_sku_id,
        quantity: item.quantity,
        unit_price: item.unit_price,
        total_price: item.total_price,
        created_at: toISOStringSafe(item.created_at),
        updated_at: toISOStringSafe(item.updated_at),
        deleted_at: item.deleted_at
          ? toISOStringSafe(item.deleted_at)
          : undefined,
      }),
    ),
    shopping_mall_payments: createdOrder.shopping_mall_payments
      ? createdOrder.shopping_mall_payments.map((payment) => ({
          id: payment.id,
          shopping_mall_order_id: createdOrder.id,
          payment_method: payment.payment_method,
          payment_status: payment.payment_status,
          payment_amount: payment.payment_amount,
          payment_date: toISOStringSafe(payment.payment_date),
          created_at: toISOStringSafe(payment.created_at),
          updated_at: toISOStringSafe(payment.updated_at),
          deleted_at: payment.deleted_at
            ? toISOStringSafe(payment.deleted_at)
            : undefined,
          order: undefined,
        }))
      : [],
    shopping_mall_shipment_trackings: [],
    shopping_mall_product_reviews: [],
    shopping_mall_order_histories: [],
    shopping_mall_order_cancellations: [],
    shopping_mall_refund_requests: [],
    shopping_mall_return_shipments: [],
  };
}

