      where: { id: cartId },
      select: {
        id: true,
        shopping_mall_customer_id: true,
        deleted_at: true,
      },
    });

  if (cart.shopping_mall_customer_id !== customer.id) {
    throw new HttpException(
      "Forbidden: Shopping cart does not belong to customer",
      403,
    );
  }

  if (cart.deleted_at !== null) {
