  return {
    id: created.id,
    shopping_mall_shopping_cart_id: created.shopping_mall_shopping_cart_id,
    shopping_mall_product_sku_id: created.shopping_mall_product_sku_id,
    quantity: created.quantity,
    created_at: now,
    updated_at: now,
    deleted_at: null,
  };
}

