import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { IShoppingMallProductReview } from "@ORGANIZATION/PROJECT-api/lib/structures/IShoppingMallProductReview";
import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function putShoppingMallAdminProductReviewsId(props: {
  admin: AdminPayload;
  id: string & tags.Format<"uuid">;
  body: IShoppingMallProductReview.IUpdate;
}): Promise<IShoppingMallProductReview> {
  const { id, body } = props;

  // Verify existence
  await MyGlobal.prisma.shopping_mall_product_reviews.findUniqueOrThrow({
    where: { id },
  });

  // Update review
  const updated = await MyGlobal.prisma.shopping_mall_product_reviews.update({
    where: { id },
    data: {
      rating: body.rating,
      review_body: body.review_body,
      moderation_status: body.moderation_status,
      updated_at: toISOStringSafe(new Date()),
    },
  });

  return {
    id: updated.id,
    shopping_mall_product_sku_id: updated.shopping_mall_product_sku_id,
    shopping_mall_customer_id: updated.shopping_mall_customer_id,
    shopping_mall_order_id: updated.shopping_mall_order_id,
    rating: updated.rating,
    review_body: updated.review_body ?? undefined,
    moderation_status: updated.moderation_status,
    created_at: toISOStringSafe(updated.created_at),
    updated_at: toISOStringSafe(updated.updated_at),
    deleted_at: updated.deleted_at ? toISOStringSafe(updated.deleted_at) : null,
  };
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { AdminPayload } from "../decorators/payload/AdminPayload";

export async function deleteShoppingMallAdminProductReviewsId(props: {
  admin: AdminPayload;
  id: string & tags.Format<"uuid">;
}): Promise<void> {
  const { admin, id } = props;

  // Verify admin existence and non-deletion
  const adminRecord = await MyGlobal.prisma.shopping_mall_admins.findFirst({
    where: { id: admin.id, deleted_at: null },
    select: { id: true },
  });

  if (!adminRecord) {
    throw new HttpException("Unauthorized: Admin not found or deleted", 403);
  }

  try {
    await MyGlobal.prisma.shopping_mall_product_reviews.delete({
      where: { id },
    });
  } catch (error) {
    if (
      error instanceof Prisma.PrismaClientKnownRequestError &&
      error.code === "P2025"
    ) {
      throw new HttpException("Product review not found", 404);
    }
    throw error;
  }
}

import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/client";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";
import { MyGlobal } from "../MyGlobal";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

import { CustomerPayload } from "../decorators/payload/CustomerPayload";

export async function deleteShoppingMallCustomerProductReviewsId(props: {
  customer: CustomerPayload;
  id: string & tags.Format<"uuid">;
}): Promise<void> {
  const review = await MyGlobal.prisma.shopping_mall_product_reviews.findUnique(
    {
      where: { id: props.id },
      select: { shopping_mall_customer_id: true },
    },
  );

  if (review === null) {
    throw new HttpException("Not Found", 404);
  }

  if (review.shopping_mall_customer_id !== props.customer.id) {
    throw new HttpException(
      "Forbidden: You can only delete your own reviews",
      403,
    );
  }

  await MyGlobal.prisma.shopping_mall_product_reviews.delete({
    where: { id: props.id },
  });
}

